K.Diagnostics={Build="Rivals-2026-11-03-kicia-ui-r25",Errors={},Calls={}}
function K.RecordError(feature,problem)
    local now=os.clock()
    local record=K.Diagnostics.Errors[feature]or{Count=0}
    K.Diagnostics.Errors[feature]=record
    record.Count+=1;record.Message=tostring(problem);record.LastAt=now
    if not record.WarnedAt or now-record.WarnedAt>5 then
        record.WarnedAt=now;warn("[Kicia] "..feature..": "..record.Message)
    end
end
function K.Safe(feature,fn,...)
    local restore=K.identity and K.identity(8)
    local results=table.pack(pcall(fn,...))
    if restore then restore()end
    K.Diagnostics.Calls[feature]=(K.Diagnostics.Calls[feature]or 0)+1
    if not results[1]then K.RecordError(feature,results[2]);return nil end
    return table.unpack(results,2,results.n)
end

function K.Step(feature,fn,self,dt)
    local ok,err=pcall(fn,self,dt)
    K.Diagnostics.Calls[feature]=(K.Diagnostics.Calls[feature]or 0)+1
    if not ok then K.RecordError(feature,err)end
end
function K.FramePhase(fn)
    return function(dt)
        if K.destroyed then return end
        local old=getthreadidentity_ and getthreadidentity_() or nil
        if setthreadidentity_ and old~=8 then pcall(setthreadidentity_,8)end
        local ok,err=pcall(fn,dt)
        if setthreadidentity_ and old and old~=8 then pcall(setthreadidentity_,old)end
        if not ok then K.RecordError("Frame callback",err)end
    end
end


function K.Unload()
    if K.destroyed then return end
    K.destroyed=true
    for i=#K.cleanups,1,-1 do pcall(K.cleanups[i]) end
    for _,connection in ipairs(K.connections) do pcall(function() connection:Disconnect() end) end
    if getgenv().KiciaRun==K then getgenv().KiciaRun=nil end
    if getgenv().AbsenseRun==K then getgenv().AbsenseRun=nil end
end

