        RightUpperArm = "Right Upper Arm", RightLowerArm = "Right Lower Arm", RightHand = "Right Hand",
        LeftUpperLeg = "Left Upper Leg", LeftLowerLeg = "Left Lower Leg", LeftFoot = "Left Foot",
        RightUpperLeg = "Right Upper Leg", RightLowerLeg = "Right Lower Leg", RightFoot = "Right Foot",
    }
    API.DefaultHitboxes = { HitboxHead = true, HitboxBody = true, HitboxHeadSmall = true, HitboxBodySmall = true }
    API.ClassOptions = { Standard = { "HitboxHead", "HitboxBody" }, Small = { "HitboxHeadSmall", "HitboxBodySmall" } }
    for _, options in pairs(API.ClassOptions) do
        for _, name in ipairs(limbs) do options[#options + 1] = name end
    end
    function API.Profile(class)
        local set = {}
        for _, name in ipairs(API.ClassOptions[class]) do set[name] = true end
        return { Class = class, HitboxSet = set,
            CriticalDamageHitboxes = { [class == "Small" and "HitboxHeadSmall" or "HitboxHead"] = true } }
    end
    function API.UpdateParts(model, result)
        result = result or {}
        table.clear(result)
        if not model then return result end
        for key, names in pairs(aliases) do
            for _, name in ipairs(names) do
                local part = model:FindFirstChild(name)
                if part and part:IsA("BasePart") then result[key] = part; break end
            end
        end
        return result
    end
    function API.ResolveParts(state, enabled, result)
        result = result or {}
        table.clear(result)
        local seen = {}
        for name, selected in pairs(enabled or {}) do
            local part = state.TargetPartsByName and state.TargetPartsByName[name]
            if selected == true and part and part.Parent == state.Model and not seen[part] then
