    function API.OrderedOptions(class, settings)
        local result, seen = {}, {}
        for _, name in ipairs(API.ClassOptions[class] or {}) do
            if settings[name] ~= nil then result[#result + 1] = name; seen[name] = true end
        end
        local extra = {}
        for name in pairs(settings) do if not seen[name] then extra[#extra + 1] = name end end
        table.sort(extra)
        for _, name in ipairs(extra) do result[#result + 1] = name end
        return result
    end
    local legacyRarities = { "None", "Unique", "Common", "Rare", "Legendary", "Mythical", "Unobtainable" }
    function API.Rarities(library)
        local result, seen = {}, {}
        local function add(name)
            if type(name) == "string" and name ~= "" and not seen[name] then
                seen[name] = true; result[#result + 1] = name
            end
        end
        for _, name in ipairs(legacyRarities) do add(name) end
        add("Genuine")
        local extra = {}
        for name in pairs(library.Rarities or {}) do if type(name) == "string" then extra[name] = true end end
        for _, item in pairs(library.Cosmetics or {}) do
            if type(item) == "table" and type(item.Rarity) == "string" then extra[item.Rarity] = true end
        end
        local ordered = {}
        for name in pairs(extra) do ordered[#ordered + 1] = name end
        table.sort(ordered)
        for _, name in ipairs(ordered) do add(name) end
        return result
    end
    function API.MigrateRarities(selected, options, schema)
        local result = table.clone(selected or {})
        if schema == 1 then return result end
        
        for _, name in ipairs(legacyRarities) do if result[name] ~= true then return result end end
        for _, name in ipairs(options) do if result[name] == nil then result[name] = true end end
        return result
    end
    function API.SearchMatch(name, query)
        local function clean(value) return tostring(value or ""):lower():gsub("[^%w]", "") end
        return string.find(clean(name), clean(query), 1, true) ~= nil
    end
    return API
end)()


