local function fn35()


local loadedModules=K.fn("getloadedmodules")
local function isLoaded(module)
    if not loadedModules then return nil end
    local ok,list=pcall(loadedModules)
    if not ok or type(list)~="table" then return nil end
    local path=module:GetFullName()
    for _,entry in pairs(list) do
        if entry==module then return true end
        
        
        local named,name=pcall(function() return entry:GetFullName() end)
        if named and name==path then return true end
    end
    return false
end

return function(root,path,loadModule,timeout)
    local parts=type(path)=="string" and {path} or path
    for _,name in ipairs(parts) do
        K.loadingModule=tostring(name)
        if root==nil then error("[Kicia] Missing parent while resolving "..name,2) end
        root=root:WaitForChild(name,timeout or 20)
        if root==nil then
            if timeout~=nil then return nil end
            error("[Kicia] Timed out waiting for "..name,2)
        end
        root=cloneref(root)
    end
    if not loadModule then return root end
    local fullName=root:GetFullName()
    K.loadingModule=fullName
    
    
    local controller=string.find(fullName,"PlayerScripts.Controllers.",1,true)~=nil
        or root.Name=="ReplicatedController"
    if controller then
        local deadline=os.clock()+30
        while isLoaded(root)==false do
            if K.destroyed then error("[Kicia] Startup cancelled",2) end
            if os.clock()>=deadline then
                error("[Kicia] Game has not initialized "..fullName.."; retry after the game finishes loading",2)
            end
            task.wait(0.1)
        end
    end
    if K.destroyed then error("[Kicia] Startup cancelled",2) end
    local identity=getthreadidentity()
    setthreadidentity(2)
    local ok,result=pcall(require,root)
    setthreadidentity(identity)
    if not ok then
        error("[Kicia] Failed to load "..fullName..": "..tostring(result)
            ..". A failed native module may remain cached until this Roblox client rejoins.",2)
    end
    K.loadingModule=nil
    return result
end
end

