local function searchShotOrigin(visibility,origin,part,radius,budget)
    if not visibility or not part or not part.Parent then return false,nil end
    radius=math.clamp(tonumber(radius) or 9.9,0,9.9)
    budget=math.clamp(math.floor(tonumber(budget) or 28),8,32)
    local target=part.Position
    local delta=target-origin
    local distance=delta.Magnitude
    local function check(point)
        return visibility:Check(point,part,part.Parent,{Point=target,Surface=false})
    end
    local clear,hit=check(origin)
    if clear then return true,origin end
    if distance<.001 or radius<.01 then return false,nil end
    local forward=delta/distance
    local right=forward:Cross(math.abs(forward.Y)>.98 and Vector3.xAxis or Vector3.yAxis).Unit
    local up=right:Cross(forward).Unit
    local candidates={}
    local function add(offset)
        if offset.Magnitude>radius then offset=offset.Unit*radius end
        for _,p in ipairs(candidates) do if (offset-p).Magnitude<.12 then return end end
        candidates[#candidates+1]=offset
    end
    
    if hit and hit.Distance then add(forward*math.min(radius,hit.Distance+.3)) end
    add(forward*math.min(radius,math.max(0,distance-part.Size.Magnitude*.5-.05)))
    add(up*radius);add(-up*radius);add(right*radius);add(-right*radius)
    for _,scale in ipairs({1,.55}) do
        for i=0,7 do
            local angle=math.pi*2*i/8
            add((right*math.cos(angle)+up*math.sin(angle))*radius*scale)
        end
    end
    if hit and hit.Normal then
        add(hit.Normal*radius)
        add((hit.Normal+up).Unit*radius);add((hit.Normal-up).Unit*radius)
        add((hit.Normal+right).Unit*radius);add((hit.Normal-right).Unit*radius)
    end
    for i=1,math.min(#candidates,budget) do
        local point=origin+candidates[i]
        if check(point) then return false,point end
    end
    return false,nil
end


