arg2:Add(task.spawn(function()
while true do
task.wait(v117.Data.Weather.Lightning.Interval)

if v117.Data.Weather.Lightning.Enabled then
arg:_FireStrike()
end
end
end))
end

index2._FireStrike = function(arg)
local currentCamera = v120.CurrentCamera
if currentCamera == nil then
return
end
local lightning = v117.Data.Weather.Lightning
local height = lightning.Height
local position = currentCamera.CFrame.Position
local tau = math.tau
local n = math.random() * tau
local distance = lightning.Distance
local n33 = math.min(v116.LightningRadiusMin, distance)
local n34 = n33 + math.random() * (distance - n33)
local n35 = position.X + math.cos(n) * n34
local n36 = position.Z + math.sin(n) * n34
local raycastParams = RaycastParams.new()
raycastParams.FilterType = Enum.RaycastFilterType.Exclude
local character = v121.LocalPlayer and v121.LocalPlayer.Character

if character then
raycastParams.FilterDescendantsInstances = { character }
end

local n37 = position.Y - v116.LightningGroundDrop
local hit = v120:Raycast(Vector3.new(n35, position.Y + height, n36), Vector3.new(0, -v116.LightningRayLength, 0), raycastParams)

if hit then
n37 = hit.Position.Y
end

local vector = Vector3.new(n35, n37, n36)
local vector2 = Vector3.new
local lightningJitter = v116.LightningJitter
local n38 = n35 + (math.random() - 0.5) * lightningJitter
local lightningJitter2 = v116.LightningJitter

local tbl18 = {
Color = lightning.Color,
Thickness = lightning.Thickness,
MaxRadius = lightning.Jaggedness,
Branches = lightning.Branches,
FlashBrightness = lightning.Flash,
Sparks = {
Enabled = lightning.Sparks.Enabled,
Color = lightning.Sparks.Color,
Count = lightning.Sparks.Count,
Thickness = lightning.Sparks.Thickness,
Distance = lightning.Sparks.Distance,
Speed = lightning.Sparks.Speed,
Jaggedness = lightning.Sparks.Jaggedness,
},
Explosion = {
Enabled = lightning.Explosion.Enabled,
Size = lightning.Explosion.Size,
Bolts = lightning.Explosion.Bolts,
Color = lightning.Explosion.Color,
},
}

arg._lightning:Strike(vector2(n38, n37 + height, n36 + (math.random() - 0.5) * lightningJitter2), vector, tbl18)

if lightning.Sound.Enabled then
local v122 = fn38(lightning.Sound.SoundId)

if v122 ~= nil then
local volume = lightning.Sound.Volume
local delay = lightning.Sound.Delay
arg:_PlayThunder(math.sqrt((n35 - position.X) ^ 2 + (n36 - position.Z) ^ 2), volume, delay, v122)
end
end
end

index2._PlayThunder = function(arg, arg2, arg3, arg4, soundId)
local n = arg4 and arg2 / v116.ThunderSpeed or 0
local volume = arg3 * math.max(v116.ThunderVolumeFloor, 1 - arg2 / v116.ThunderFalloff)
local n33 = v116.ThunderPitchMax - v116.ThunderPitchMin
local playbackSpeed = v116.ThunderPitchMin + math.random() * n33
local activeTrove = arg._activeTrove
if activeTrove == nil then
return
end

activeTrove:Add(task.delay(n, function()
local sound = Instance.new("Sound")
sound.SoundId = soundId
sound.Volume = volume
sound.PlaybackSpeed = playbackSpeed
sound.PlayOnRemove = true
sound.Parent = v119
sound:Destroy()
end))
end

index2._Reconcile = function(arg)
local weather = v117.Data.Weather
local intensity = weather.Intensity
local rate = weather.Rate
local speed = weather.Speed
local size = weather.Size
local glow = weather.Glow
local spread = weather.Spread
local colorSequence = ColorSequence.new(weather.Color)
local v122 = math.rad(weather.Wind.Angle)
local strength = weather.Wind.Strength
local n = math.sin(v122) * strength
local n33 = math.cos(v122) * strength
arg._height = weather.Height

for _, v123 in arg._emitters, nil, nil do
local emitter = v123.Emitter
local spec = v123.Spec
emitter.Rate = spec.BaseRate * intensity * rate
emitter.Speed = NumberRange.new(spec.SpeedMin * speed, spec.SpeedMax * speed)
emitter.Size = fn37(NumberSequence.new(spec.SizeStart, spec.SizeEnd), size)
emitter.LightEmission = glow
local n34 = spec.BaseSpread * spread
emitter.SpreadAngle = Vector2.new(n34, n34)
emitter.Color = colorSequence
emitter.Acceleration = Vector3.new(n, spec.BaseAccelerationY, n33)
end
end

index2.Update = function(arg)
arg._lightning:Update()

if arg._activeTrove then
local currentCamera = v120.CurrentCamera

if currentCamera then
arg._part.Position = currentCamera.CFrame.Position + Vector3.new(0, arg._height, 0)
end
end
end

return index2
end

