local kiciaLayout = {}

function kiciaLayout.Movement(grid)
    local ground=grid:AddSection({Title="Ground movement",Side="left"})
    local air=grid:AddSection({Title="Air movement",Side="right"})
    local function slider(section,label,key,min,max)
        local toggle=section:AddToggle({Label=label,Config={"Movement",key,"Enabled"}})
        section:AddGroup({Source=toggle}):AddSlider({Label=label.." multiplier",Min=min,Max=max,Step=.01,Config={"Movement",key,"Speed"}})
    end
    slider(ground,"Walk Speed","WalkSpeed",1,10)
    slider(ground,"Sliding Speed","Sliding",1,10)
    slider(air,"Jump Power","JumpPower",.1,10)
    air:AddToggle({Label="Infinite Double Jumps",Config={"ItemModifiers","InfiniteDoubleJumps"}})
end

function kiciaLayout.RageMovement(grid)
    local bind=tbl17.h6()
    local ground=grid:AddSection({Title="Collision & strafing",Side="left"})
    local air=grid:AddSection({Title="Flight & long jump",Side="right"})
    bind(ground,"Noclip",{"Toggle","Hold"},{"Movement","Noclip"},true)
    local strafe=bind(ground,"Auto Strafe",{"Toggle","Hold"},{"Movement","AutoStrafe"},true)
    ground:AddGroup({Source=strafe}):AddSlider({Label="Strafe speed",Min=1,Max=200,Config={"Movement","AutoStrafe","Speed"}})
    local flight=bind(air,"Flight",{"Toggle","Hold"},{"Movement","Flight"},true)
    air:AddGroup({Source=flight}):AddSlider({Label="Flight speed",Min=25,Max=500,Config={"Movement","Flight","Speed"}})
    local jump=bind(air,"Long Jump",{"Tap"},{"Movement","LongJump"},true)
    local j=air:AddGroup({Source=jump})
    j:AddDropdown({Label="Direction",Options={"Under Feet","Camera Look"},Config={"Movement","LongJump","Mode"}})
    j:AddSlider({Label="Force",Min=0,Max=300,Config={"Movement","LongJump","Force"}})
    j:AddSlider({Label="Upward Velocity",Min=0,Max=200,Config={"Movement","LongJump","UpwardVelocity"}})
    j:AddSlider({Label="Behind Offset",Min=0,Max=8,Step=.1,Config={"Movement","LongJump","Behind"}})
    local firing=grid:AddSection({Title="Fire handling",Side="left"})
    firing:AddToggle({Label="Automatic Fire",Config={"ItemModifiers","AutomaticWeapon"}})
    for _,entry in ipairs({{"Fire Cooldown","FireCooldown",0,100},{"Aim Cooldown","AimCooldown",1,100},{"Aim Speed","AimSpeed",50,500}}) do
        local t=firing:AddToggle({Label=entry[1].." Override",Config={"ItemModifiers",entry[2],"Enabled"}})
        firing:AddGroup({Source=t}):AddSlider({Label=entry[1].." (%)",Min=entry[3],Max=entry[4],Step=1,Config={"ItemModifiers",entry[2],"Percentage"}})
    end
end

function kiciaLayout.Weapon(grid)
    local recoil=grid:AddSection({Title="Recoil & spread",Side="left"})
    local r=recoil:AddToggle({Label="Reduce Recoil",Config={"ItemModifiers","Recoil","Enabled"},OnChanged=function(v)
        tbl17.bG():Set({"Ragebot","WildcatPullDown","Enabled"},v)
    end})
    local reduction=recoil:AddGroup({Source=r})
    reduction:AddSlider({Label="Recoil Reduction (%)",Min=0,Max=100,Step=1,Config={"ItemModifiers","Recoil","Percentage"}})
    reduction:AddSlider({Label="Wildcat Pull-down (px/s)",Min=0,Max=600,Step=5,Config={"Ragebot","WildcatPullDown","Strength"}})
    recoil:AddToggle({Label="Remove Spread",Config={"ItemModifiers","NoSpread"}})
    local knife=grid:AddSection({Title="Knife & melee",Side="right"})
    knife:AddToggle({Label="Always Backstab",Config={"ItemModifiers","AlwaysBackstab"}})
    local range=knife:AddToggle({Label="Extend Melee Range",Config={"ItemModifiers","ExtendMeleeRange","Enabled"}})
    knife:AddGroup({Source=range}):AddSlider({Label="Melee Range",Min=5,Max=20,Step=.5,Config={"ItemModifiers","ExtendMeleeRange","Range"}})
    local speed=knife:AddToggle({Label="Melee Cooldown Override",Config={"ItemModifiers","MeleeCooldown","Enabled"}})
    knife:AddGroup({Source=speed}):AddSlider({Label="Melee Cooldown (%)",Min=0,Max=100,Step=1,Config={"ItemModifiers","MeleeCooldown","Percentage"}})
    local dash=grid:AddSection({Title="Dash",Side="left"})
    local d=dash:AddToggle({Label="Dash Cooldown Override",Config={"ItemModifiers","DashCooldown","Enabled"}})
    dash:AddGroup({Source=d}):AddSlider({Label="Dash Cooldown (%)",Min=0,Max=100,Step=1,Config={"ItemModifiers","DashCooldown","Percentage"}})
    local fuse=grid:AddSection({Title="Grenades",Side="right"})
    local f=fuse:AddToggle({Label="Fuse Override",Config={"ItemModifiers","GrenadeFuse","Enabled"}})
    local g=fuse:AddGroup({Source=f})
    g:AddDropdown({Label="Explode On",Options={"Impact","Throw"},Config={"ItemModifiers","GrenadeFuse","ExplodeOn"}})
    g:AddToggle({Label="Remove Fuse",Config={"ItemModifiers","GrenadeFuse","RemoveFuse"}})
end

function kiciaLayout.Attack(grid)
    local main=grid:AddSection({Title="Ragebot",Side="left"})
    tbl17.h6()(main,"Enable Ragebot",{"Toggle"},{"Ragebot"},true)
    main:AddToggle({Label="Anti Out of Bounds",Config={"Ragebot","Safety","AntiOutOfBounds"}})
    main:AddToggle({Label="Prioritize Hackers",Config={"Ragebot","PrioritizeHackers"}})
    main:AddDropdown({Label="Cover Strategy",Options={"Adaptive","Hide","Inside","Underground"},
        Labels={Adaptive="Adaptive",Hide="Hide below target",Inside="Close to target",Underground="Under the map"},
        Tooltip="Standard gun placement. Knife and projectile-specific modes keep their own attack positioning.",
        Config={"Ragebot","Engine","Positioning"}})
    local firing=grid:AddSection({Title="Attack",Side="left"})
    local mode=firing:AddDropdown({Label="Mode",Options={"Standard","Knife"},Config={"Ragebot","Engine","Mode"}})
    firing:AddGroup({Source=mode,Option="Knife"}):AddDropdown({Label="Contact Timing",Options={"BeforeAttack","AfterAttack"},
        Labels={BeforeAttack="Before attack",AfterAttack="After attack (experimental)"},Config={"Ragebot","Knife","Timing"}})
    local timing=firing:AddDropdown({Label="Attack Timing",Options={"Minimum","Custom"},Labels={Minimum="Automatic",Custom="Custom"},Config={"Ragebot","Engine","Timing"}})
    local custom=firing:AddGroup({Source=timing,Option="Custom"})
    custom:AddSlider({Label="Position Settle (MS)",Min=0,Max=250,Step=1,Config={"Ragebot","Engine","SettleMS"}})
    custom:AddSlider({Label="Hold After Shot (MS)",Min=0,Max=250,Step=1,Config={"Ragebot","Engine","HoldMS"}})
    firing:AddSlider({Label="Attack Attempts",Min=1,Max=4,Step=1,Config={"Ragebot","Engine","BurstRequests"}})
    firing:AddToggle({Label="Projectile Prediction",Config={"Ragebot","Engine","Prediction"}})
    firing:AddToggle({Label="Follow Moving Targets",Config={"Ragebot","Engine","FollowTarget"},
        Tooltip="Follows ordinary movement during the attack window. Teleports cause a fresh placement."})
    firing:AddToggle({Label="Confirm Knife / Sniper Hits",Config={"Ragebot","Engine","ConfirmHits"}})
    local safety=grid:AddSection({Title="Combat safety",Side="left"})
    safety:AddToggle({Label="Safer Firing Positions",Config={"Ragebot","Safety","SaferPositions"},
        Tooltip="For Adaptive placement: weighs weapon spread, nearby melee reach, and exposure to other shooters."})
    safety:AddToggle({Label="Retreat After Damage",Config={"Ragebot","Safety","RetreatOnDamage"},
        Tooltip="A hit of 6 or more health during an attack triggers a brief retreat and rejects that spot temporarily."})
    safety:AddToggle({Label="Retreat With Health Lead",Config={"Ragebot","Safety","HealthLead"}})
    safety:AddToggle({Label="Shield-aware Positioning",Config={"Ragebot","Safety","ShieldAware"}})
    safety:AddToggle({Label="Avoid Active Tripmines",Config={"Ragebot","Safety","AvoidTripmines"}})
    safety:AddToggle({Label="Map-aware Void Pauses",Config={"Ragebot","Safety","VoidPauses"}})
    local targets=grid:AddSection({Title="Target priority",Side="right"})
    local priority=targets:AddDropdown({Label="Priority",Options={"LowestHealth","Closest","VoidedFirst"},
        Labels={LowestHealth="Lowest health",Closest="Closest",VoidedFirst="Voided first"},Config={"Ragebot","Targeting","Priority"}})
    targets:AddGroup({Source=priority,Option="VoidedFirst"}):AddSlider({Label="Void Distance",Min=10000,Max=1000000,Step=10000,Config={"Ragebot","Targeting","VoidDistance"}})
    targets:AddMultiDropdown({Label="Priority Players",Options={},Search=true,Config={"Ragebot","Targeting","PriorityPlayers"},GetOptions=function()
        local names={} for _,p in ipairs(game:GetService("Players"):GetPlayers()) do if p~=game:GetService("Players").LocalPlayer then names[#names+1]=p.Name end end
        table.sort(names) return names
    end})
    local weapons=grid:AddSection({Title="Weapon selection",Side="right"})
    local selection=weapons:AddDropdown({Label="Use",Options={"Equipped","Priority"},
        Labels={Equipped="Equipped weapon",Priority="Weapon priority"},Config={"Ragebot","Weapons","Selection"}})
    local automatic=weapons:AddGroup({Source=selection,Option="Priority"})
    for _,slot in ipairs({"Primary","Secondary","Melee"}) do automatic:AddToggle({Label=slot,Config={"Ragebot","Weapons","Enabled",slot}}) end
    automatic:AddOrderedList({Label="Weapon Priority",Items={"Primary","Secondary","Melee"},Config={"Ragebot","Weapons","Priority"}})
    automatic:AddDropdown({Label="On Empty",Options={"Reload","Swap","SwapOrReload"},Labels={SwapOrReload="Swap or reload"},Config={"Ragebot","Weapons","OnEmpty"}})
    local status=grid:AddSection({Title="Live status",Side="right"})
    local label=status:AddLabel({Label="Ready"})
    local nextUpdate=0
    status._trove:Connect(game:GetService("RunService").Heartbeat,function()
        if not status._menu.Visible or os.clock()<nextUpdate then return end nextUpdate=os.clock()+.4
        local run=getgenv().KiciaRun local engine=run and run.Ragebot if not engine then return end
        local s=engine:GetDebugState()
        label:SetLabel(tostring(s.Status).."\n"..tostring(s.Weapon or "No weapon").."  ·  "..tostring(s.Target or "No target"))
    end)
end

function kiciaLayout.Identity(grid)
    local store=tbl17.bG()
    local scope=grid:AddSection({Title="Identity",Side="left"})
    scope:AddLabel({Label="Changes how identities are displayed on your client."})
    local choice=scope:AddDropdown({Label="Apply to",Options={"LocalPlayer","OtherPlayers"},Labels={LocalPlayer="You",OtherPlayers="Other players"},Default="LocalPlayer"})
    for _,who in ipairs({"LocalPlayer","OtherPlayers"}) do
        local basic=grid:AddSection({Title=who=="LocalPlayer" and "Your profile" or "Other players' profiles",Side="left"})
        local stats=grid:AddSection({Title="Statistics",Side="right"})
        local badges=grid:AddSection({Title="Badges & status",Side="right"})
        local sections={basic,stats,badges}
        choice:OnChanged(function(v) for _,s in ipairs(sections) do s:SetVisible(v==who) end end)
        for _,s in ipairs(sections) do s:SetVisible(who=="LocalPlayer") end
        local entries={{"Name","Name","text",basic},{"DisplayName","Display name","text",basic},{"Avatar","Avatar user ID","text",basic},
            {"Winstreak","Win streak","number",stats},{"Level","Level","number",stats},{"CasualWins","Casual wins","number",stats},
            {"RankedWins","Ranked wins","number",stats},{"CasualWinPercent","Casual win rate","percent",stats},
            {"RankedWinPercent","Ranked win rate","percent",stats},{"RankedElo","Ranked ELO","number",stats},
            {"LeaderboardRank","Leaderboard rank","number",stats},{"FavoriteMap","Favorite map","text",stats},
            {"NametagStatus","Nametag status","status",badges},{"Influencer","Influencer","flag",badges},
            {"RobloxEmployee","Roblox employee","flag",badges},{"NosniyTeam","Nosniy team","flag",badges}}
        if who=="LocalPlayer" then
            table.insert(entries,{"Ping","Ping","ping",stats});table.insert(entries,{"Keys","Keys","number",stats});table.insert(entries,{"EventCurrency","Event currency","number",stats})
        end
        for _,entry in ipairs(entries) do
            local key,label,kind,section=unpack(entry)
            local t=section:AddToggle({Label=label,Config={"PlayerSpoofer",who,key,"Enabled"}})
            local group=section:AddGroup({Source=t}) local path={"PlayerSpoofer",who,key,"Value"}
            if kind=="text" then group:AddTextBox({Label=label.." value",Config=path})
            elseif kind=="percent" then group:AddSlider({Label=label.." (%)",Min=0,Max=100,Step=.1,Config=path})
            elseif kind=="status" or kind=="ping" then group:AddDropdown({Label=label.." value",Options=kind=="status" and {"Prime","Contraband"} or {"Low","Medium","High"},Config=path})
            elseif kind=="number" then
                local box=group:AddTextBox({Label=label.." value"})
                box:Set(tostring(store:Get(path) or 0),true)
                box:OnChanged(function(v) local n=tonumber(v) if n and n==n and math.abs(n)<math.huge then store:Set(path,math.max(0,math.floor(n))) end end)
                box:Connect(store:GetPropertyChangedSignal(path),function(v) box:Set(tostring(v or 0),true) end)
            end
        end
    end
end

function kiciaLayout.Visuals(context,menu)
    local grid=menu:AddTab({Label="Visuals"}):AddTab({Label="Player ESP"}):Grid({Columns=2})
    local store=tbl17.bG()
    local main=grid:AddSection({Title="Player ESP",Side="left"})
    tbl17.h6()(main,"Enable ESP",{"Toggle","Hold","Always"},{"Esp","Main"},true)
    local edit=main:AddDropdown({Label="Style for",Options={"Enemy","Team"},Labels={Enemy="Enemies",Team="Teammates"},Default="Enemy"})
    local features={"Enabled","Box","FilledBox","Name","HealthBar","HealthNumber","HeldWeapon","AmmoBar","Distance","Rank","Winstreak","Deflecting","Chams","Skeleton","HeadMarker","Tracer"}
    local labels={Enabled="Show this team",Box="Box",FilledBox="Box fill",Name="Name",HealthBar="Health bar",HealthNumber="Health number",
        HeldWeapon="Held weapon",AmmoBar="Ammo bar",Distance="Distance",Rank="Rank",Winstreak="Win streak",Deflecting="Deflecting",
        Chams="Chams",Skeleton="Skeleton",HeadMarker="Head marker",Tracer="Tracer"}
    for _,team in ipairs({"Enemy","Team"}) do
        local group=main:AddGroup({Source=edit,Option=team})
        local function selection()
            local cfg=store.Data.Esp[team];local out={Enabled=cfg.Enabled==true}
            for _,key in ipairs(features)do if key~="Enabled"then out[key]=cfg[key].Enabled==true end end
            return out
        end
        local list=group:AddMultiDropdown({Label="Show overlays",Options=features,Labels=labels,Default=selection()})
        list:OnChanged(function(value)
            for _,key in ipairs(features)do
                local path=key=="Enabled" and {"Esp",team,"Enabled"} or {"Esp",team,key,"Enabled"}
                if store:Get(path)~=(value[key]==true)then store:Set(path,value[key]==true)end
            end
        end)
        list:Connect(store:GetPropertyChangedSignal({"Esp",team}),function()list:Set(selection(),true)end)
    end
    local details=grid:AddSection({Title="Overlay appearance",Side="left"})
    local options={}for _,key in ipairs(features)do if key~="Enabled"then options[#options+1]=key end end
    local inspect=details:AddDropdown({Label="Edit overlay",Options=options,Labels=labels,Default="Box"})
    local styleGroups={}
    for _,team in ipairs({"Enemy","Team"})do
        for _,key in ipairs(options)do
            local group=details:AddGroup({Source=edit,Predicate=function(scope)return scope==team and inspect.Value==key end})
            styleGroups[#styleGroups+1]=group
            local function path(field)return {"Esp",team,key,field}end
            local function tint(label,field,alpha,gradient)
                group:AddColor({Row=group:AddLabel({Label=label}).Row,Config=path(field),Alpha=alpha~=nil,
                    Transparency=alpha and path(alpha) or nil,Gradient=gradient and "editable" or nil})
            end
            if key=="Chams"then
                group:AddDropdown({Label="Chams style",Options={"Legacy","Highlight"},Config=path("Kind")})
                tint("Fill","InnerColor","InnerTransparency")
                tint("Outline","OutlineColor","OutlineTransparency")
            else
                local gradient=key=="FilledBox" or key=="HealthBar" or key=="AmmoBar" or key=="Skeleton" or key=="Tracer"
                local cfg=store.Data.Esp[team][key]
                tint("Colour","Color",cfg.Transparency~=nil and "Transparency" or nil,gradient)
                if key=="Box"then
                    group:AddDropdown({Label="Box style",Options={"Full","Corner"},Config=path("Style")})
                    group:AddDropdown({Label="Box fit",Options={"Static","Dynamic"},Config={"Esp","Main","Mode"}})
                elseif key=="HealthBar" or key=="AmmoBar"then
                    group:AddDropdown({Label="Colour mode",Options={"Solid","Gradient","Reactive"},Config=path("ColorMode")})
                elseif key=="Skeleton" or key=="Tracer"then
                    group:AddSlider({Label="Thickness",Min=1,Max=6,Config=path("Thickness")})
                    if key=="Tracer"then group:AddDropdown({Label="Start from",Options={"Bottom","Center","Top","Mouse"},Config=path("Origin")})end
                elseif key=="HeadMarker"then
                    group:AddDropdown({Label="Shape",Options={"Cross","Circle","Diamond"},Config=path("Shape")})
                    group:AddToggle({Label="Filled",Config=path("Filled")})
                end
            end
        end
    end
    inspect:OnChanged(function()for _,group in ipairs(styleGroups)do group._applyGroup()end end)
    
    
    local preview=grid:AddSection({Title="ESP preview",Side="right"})
    local sample=preview:AddLabel({Label="ENEMY  •  Player  •  70 HP  •  25 m",TextSize=14})
    local function refreshPreview()
        local scope=edit.Value=="Team" and "TEAMMATE" or "ENEMY"
        sample:SetLabel(scope.."  •  Player  •  70 HP  •  25 m")
    end
    edit:OnChanged(refreshPreview)
    menu._espPreview={Scope=edit,Refresh=refreshPreview}
    refreshPreview()
end

