function kiciaLayout.Cosmetics(context,menu)
    local catalog=tbl17.eT()
    local weapons=table.clone(tbl17.aT())
    table.sort(weapons)
    local cosmetics,config=context.Cosmetics,context.CosmeticsConfig
    local top=menu:AddTab({Label="Cosmetics"})
    local page=top:AddTab({Label="Equipment"})
    local grid=page:Grid({Columns=2})
    local outfit=grid:AddSection({Title="Skin Changer",Side="left"})
    local unlock=outfit:AddToggle({Label="Unlock All",Default=cosmetics:IsUnlockerEnabled()})
    local selectedWeapon="Assault Rifle"
    local weapon=outfit:AddDropdown({Label="Weapon",Options=weapons,Default=selectedWeapon,Search=true})
    local enabled=outfit:AddToggle({Label="Skin Changer",Default=cosmetics._runtimeEnabled and cosmetics:IsSkinChangerEnabled()})
    local saved=outfit:AddLabel({Label="Selections save automatically."})
    local labels={}
    for _,kind in ipairs({"Skin","Wrap","Charm","Finisher"}) do labels[kind]=outfit:AddLabel({Label=kind..": Original"}) end
    local tools=grid:AddSection({Title="Apply & manage",Side="left"})
    local inverted=tools:AddToggle({Label="Invert Wrap"})
    local selection=grid:AddSection({Title="Collection",Side="right"})
    local category=selection:AddDropdown({Label="Browse",Options={"Skin","Wrap","Charm","Finisher"},Labels={Skin="Skins",Wrap="Wraps",Charm="Charms",Finisher="Finishers"},Default="Skin"})
    local count=selection:AddLabel({Label=""})
    local picker=selection:AddSkinChanger({HeightMode="Fill",State="Ready"})
    local busy=false
    local function previewItem(kind,name)
        return function(_,host)
            local assets=game:GetService("Players").LocalPlayer:FindFirstChild("PlayerScripts")
            assets=assets and assets:FindFirstChild("Assets")
            local template
            if kind=="Wrap" then template=assets and assets:FindFirstChild("Misc") and assets.Misc:FindFirstChild("Wrap")
            elseif kind=="Charm" then template=assets and assets:FindFirstChild("Charms") and assets.Charms:FindFirstChild(name) end
            if not template then return end
            local model=template:Clone()
            if kind=="Wrap" then
                local wrap=tbl17.em()
                wrap.applyWrap(wrap.recordOriginalProperties(model),name)
            end
            local viewport=Instance.new("ViewportFrame")
            viewport.Size=UDim2.fromScale(1,1);viewport.BackgroundTransparency=1
            viewport.Ambient=Color3.fromRGB(190,190,190);viewport.LightColor=Color3.new(1,1,1)
            viewport.Parent=host.Content
            local camera=Instance.new("Camera");camera.FieldOfView=30;camera.Parent=viewport;viewport.CurrentCamera=camera
            model.Parent=viewport
            local cf,size
            if model:IsA("Model") then model:PivotTo(CFrame.identity);cf,size=model:GetBoundingBox()
            elseif model:IsA("BasePart") then model.CFrame=CFrame.identity;cf,size=model.CFrame,model.Size
            else viewport:Destroy();return end
            local distance=math.max(size.X,size.Y,size.Z)/math.tan(math.rad(15))*.7
            camera.CFrame=CFrame.lookAt(cf.Position+Vector3.new(distance*.6,distance*.3,distance),cf.Position)
            host.HideImage()
        end
    end
    local function name(value)
        if type(value)=="table" then value=value.Name end
        if value==nil then return "Original" end
        return ({NONE_COSMETIC="None",RANDOM_COSMETIC="Random"})[value] or value
    end
    local function current()
        return cosmetics:GetSkinChangerSelections(selectedWeapon) or {}
    end
    local function refresh()
        busy=true
        local c=current()
        for kind,label in pairs(labels) do label:SetLabel(kind..": "..name(c[kind])) end
        inverted:Set(c.Wrap and c.Wrap.Inverted==true or false,true)
        picker:Set(name(c[category.Value]),true)
        enabled:Set(cosmetics._runtimeEnabled and cosmetics:IsSkinChangerEnabled(),true)
        unlock:Set(cosmetics:IsUnlockerEnabled(),true)
        busy=false
    end
    local function collection()
        local kind=category.Value
        local names=kind=="Skin" and (catalog.Skins[selectedWeapon] or {}) or catalog[kind.."s"] or {}
        local items={{Name="Original",Image="rbxassetid://17562770037"},{Name="None",Image="rbxassetid://17562770037"},{Name="Random",Image="rbxassetid://94238795177693"}}
        for _,n in ipairs(names) do items[#items+1]={Name=n,Image=catalog.Images[n],Render=(kind=="Wrap" or kind=="Charm") and previewItem(kind,n) or nil} end
        picker:SetItems(items,true)
        count:SetLabel(tostring(#names).." "..string.lower(kind).."s · "..selectedWeapon)
        refresh()
    end
    local function apply(kind,value)
        local converted=({Original=false,None="NONE_COSMETIC",Random="RANDOM_COSMETIC"})[value]
        if converted==nil then converted=value end
        if converted==false then converted=nil end
        if kind=="Wrap" then
            cosmetics:SetSkinChangerChoice(selectedWeapon,{Kind="Wrap",Wrap=converted and {Name=converted,Inverted=inverted.Value} or nil})
        else cosmetics:SetSkinChangerChoice(selectedWeapon,{Kind=kind,Name=converted}) end
        saved:SetLabel("Saved · "..selectedWeapon)
        refresh()
    end
    enabled:OnChanged(function(v)
        config:SetRuntimeEnabled(v);cosmetics:SetSkinChangerEnabled(v);refresh()
    end)
    unlock:OnChanged(function(v)
        cosmetics:SetUnlockerEnabled(v)
        if v then config:SetRuntimeEnabled(true) end
        refresh()
    end)
    inverted:OnChanged(function(v)
        if busy then return end
        local wrap=current().Wrap
        if wrap then cosmetics:SetSkinChangerChoice(selectedWeapon,{Kind="Wrap",Wrap={Name=wrap.Name,Inverted=v}}) end
    end)
    weapon:OnChanged(function(v) selectedWeapon=v;collection() end)
    category:OnChanged(collection)
    picker:OnChanged(function(v) if not busy and v then apply(category.Value,v) end end)
    tools:AddButton({Label="Clear This Weapon",OnClick=function()
        for _,kind in ipairs({"Skin","Wrap","Charm","Finisher"}) do cosmetics:ClearSkinChangerSelection(selectedWeapon,kind) end
        refresh()
    end})
    tools:AddButton({Label="Randomise This Weapon",OnClick=function()
        for _,kind in ipairs({"Skin","Wrap","Charm","Finisher"}) do apply(kind,"Random") end
    end})
    local rank=grid:AddSection({Title="Rank charm",Side="left"})
    local seasons,seasonByLabel={},{}
    for _,s in ipairs(tbl17.d7().SeasonCharms or {}) do
        local text="Season "..tostring(s.Version).." · "..s.SeasonName
        seasons[#seasons+1]=text;seasonByLabel[text]=s.CharmName
    end
    local season=rank:AddDropdown({Label="Season",Options=seasons,Default=seasons[1]})
    local ranks={"Off"};for _,v in ipairs(tbl17.d7().RankNames) do ranks[#ranks+1]=v end
    local rankChoice=rank:AddDropdown({Label="Rank",Options=ranks,Default="Off"})
    local position=rank:AddTextBox({Label="Leaderboard position (optional)"})
    local function applyRank()
        local key=seasonByLabel[season.Value] if not key then return end
        local r=rankChoice.Value
        local p=tonumber(position.Value)
        cosmetics:GetRankCharm():SetForSeason(key,r~="Off" and r or nil,p and math.max(1,math.floor(p)) or nil)
    end
    rankChoice:OnChanged(applyRank);position:OnChanged(applyRank)
    local function readRank()
        local key=seasonByLabel[season.Value] if not key then return end
        local r,p=cosmetics:GetRankCharm():GetForSeason(key)
        rankChoice:Set(r or "Off",true);position:Set(p and tostring(p) or "",true)
    end
    season:OnChanged(readRank)
    local emoteGrid=top:AddTab({Label="Emotes"}):Grid({Columns=2})
    local emoteSlots=emoteGrid:AddSection({Title="Emote wheel",Side="left"})
    local slot=emoteSlots:AddDropdown({Label="Slot",Options={"1","2","3","4","5","6","7","8"},Default="1"})
    local emotePage=emoteGrid:AddSection({Title="Emote collection",Side="right"})
    local emotePicker=emotePage:AddSkinChanger({HeightMode="Fill",State="Ready"})
    local emotes={{Name="Original"}}
    for _,v in ipairs(catalog.Emotes or {}) do emotes[#emotes+1]={Name=v,Image=catalog.Images[v]} end
    emotePicker:SetItems(emotes,true)
    emotePicker:OnChanged(function(v)
        cosmetics:_SetEmote(tonumber(slot.Value),v~="Original" and v or nil,nil,true)
    end)
    local function readEmote()
        local chosen=cosmetics._emotes:GetIntent():GetAll()[tonumber(slot.Value)]
        emotePicker:Set(chosen or "Original",true)
    end
    slot:OnChanged(readEmote)
    emotePicker:Connect(config.StateConfigLoaded,readEmote)
    readEmote()
    tbl17.io()(context,top:AddTab({Label="Presets"}):Grid({Columns=2}))
    picker:Connect(config.StateConfigLoaded,function() collection();readRank() end)
    picker:Connect(cosmetics.StoresUpdated,function() if not busy then refresh() end end)
    menu._skinPicker={Weapon=weapon,Category=category,Picker=picker,Enabled=enabled,Refresh=collection,Emotes=emotePicker}
    collection();readRank()
end


