    return function(section, feature, spec)
        local rows = {}
        for class, states in pairs(spec.Classes) do
            local function add(settings, state)
                local path = { feature, "TargetHitboxes", class }
                if state then path[#path + 1] = state end
                local dropdown = section:AddMultiDropdown({
                    Label = state and (state .. " Allowed Hitboxes") or "Allowed Hitboxes",
