                    Config = path,
                })
                rows[#rows + 1] = { Dropdown = dropdown, Path = path, Class = class }
            end
            if spec.Kind == "Stateless" then add(states)
            else for _,state in ipairs({"Ground","Air"}) do if states[state] then add(states[state],state) end end end
        end
        return rows
    end
end

