end
end

local absenseDaggersMode = (function()
    local Mode = {}
    Mode.__index = Mode
    local function finite(n) return type(n)=="number" and n==n and math.abs(n)<math.huge end
    local function vector(v) return v and finite(v.X) and finite(v.Y) and finite(v.Z) end
    local function bounded(v, fallback, low, high)
        return math.clamp(finite(tonumber(v)) and tonumber(v) or fallback, low, high)
    end
    local function read(item, key)
        if not item then return nil end
        local ok, value = pcall(function() return item:Get(key) end)
        if ok and value~=nil then return value end
        return item.Data and item.Data[key]
    end
    function Mode.IsDaggers(item)
        return item and item.Info and item.Info.Type=="Gun"
            and (item.Name=="Daggers" or item.Info.Name=="Daggers")
    end
    function Mode.Precision(position)
        local scale=math.max(math.abs(position.X),math.abs(position.Y),math.abs(position.Z),1)
        return 2^(math.floor(math.log(scale)/math.log(2))-23)
    end
    function Mode.Look(origin, direction)
        local scale=math.max(math.abs(direction.X),math.abs(direction.Y),math.abs(direction.Z))
        if scale<1e-9 then return nil end
        local d=direction/scale
        local up=math.abs(d.Unit.Y)>0.99 and Vector3.zAxis or Vector3.yAxis
        return CFrame.new(origin)*CFrame.lookAt(Vector3.zero,d,up)
    end
    function Mode.HeadExtent(head, direction)
        local localDirection=head.CFrame:VectorToObjectSpace(direction.Unit)
        local half=head.Size*0.5
        local divisor=math.max(math.abs(localDirection.X)/math.max(half.X,0.01),
            math.abs(localDirection.Y)/math.max(half.Y,0.01),
            math.abs(localDirection.Z)/math.max(half.Z,0.01))
        return 1/math.max(divisor,1e-6)
    end
    function Mode.NearOffset(item, head, direction, clearance)
        local spawn=item.Info and item.Info.ProjectileSpawnOffset
        local offset=typeof(spawn)=="CFrame" and spawn.Position or Vector3.new(0,-1,-2)
        local outward=direction.Unit
        local rotation=Mode.Look(Vector3.zero,-outward)
        local radius=bounded(item.Info and item.Info.ProjectileRaycastRadius,0.25,0,2)
        local gap=math.max(bounded(clearance,0.5,0.35,3),radius+0.1,Mode.Precision(head.Position)*4)
        local launch=outward*(Mode.HeadExtent(head,outward)+gap)
        
        
        return launch-rotation:VectorToWorldSpace(offset),launch,gap
    end

    
    
    function Mode.Solve(origin, head, velocity, speed, gravity, latency, maximum)
        if not vector(origin) or not vector(head) or not vector(velocity) or not vector(gravity)
            or not finite(speed) or speed<=0 then return nil,"Invalid trajectory" end
        maximum=bounded(maximum,0.5,0.02,2)
        latency=bounded(latency,0,0,1)
        local dx,dy,dz=head.X-origin.X,head.Y-origin.Y,head.Z-origin.Z
        local function at(t)
            local x=dx+velocity.X*(latency+t)-0.5*gravity.X*t*t
            local y=dy+velocity.Y*(latency+t)-0.5*gravity.Y*t*t
            local z=dz+velocity.Z*(latency+t)-0.5*gravity.Z*t*t
            return math.sqrt(x*x+y*y+z*z)-speed*t,x,y,z
        end
        local times={}
        for i=1,64 do
            times[#times+1]=maximum*i/64
        end
        
        
        local speedSquared=velocity.X^2+velocity.Y^2+velocity.Z^2
        if speedSquared>0 then
            local closest=-((dx+velocity.X*latency)*velocity.X
                +(dy+velocity.Y*latency)*velocity.Y+(dz+velocity.Z*latency)*velocity.Z)/speedSquared
            if closest>0 and closest<maximum then times[#times+1]=closest end
        end
        table.sort(times)
        local left,right=0,nil
        for _,t in ipairs(times) do
            if at(t)<=0 then right=t;break end
            left=t
        end
        if not right then return nil,"No reachable head intercept" end
        for _=1,32 do
            local mid=(left+right)/2
            if at(mid)>0 then left=mid else right=mid end
        end
        local t=(left+right)/2
        local _,x,y,z=at(t)
        local offset=Vector3.new(x,y,z)
        if offset.Magnitude<1e-6 then return nil,"Launch overlaps target" end
        return {Time=t,Direction=offset.Unit,Offset=offset,Origin=origin,Head=head,Gravity=gravity,
            Impact=head+velocity*(latency+t),Speed=speed,Latency=latency,Velocity=velocity}
    end

    function Mode.new(engine)
        return setmetatable({Engine=engine,Generation=0,Motion=setmetatable({},{__mode="k"}),
            Pending={},Stats={Requests=0,Launches=0,Unconfirmed=0,DamageObserved=0,
                NativeDeclines=0,Teleports=0,NoIntercept=0}},Mode)
    end
    function Mode:_status(text)
        self.Engine._stats.Status=text
        self.Stats.Status=text
    end
    function Mode:_releaseJob(job)
        if not job then return end
        job.Active=false
        if rawget(job.Fighter,"GetCameraData")==job.Provider then
            rawset(job.Fighter,"GetCameraData",job.PreviousCamera)
        end
    end
    function Mode:Reset()
        self.Generation+=1
        self:_releaseJob(self.Job)
        local thread=self.Job and self.Job.Thread
        self.Job=nil
        if thread and thread~=coroutine.running() and type(task.cancel)=="function" then pcall(task.cancel,thread) end
        if self.Watch then self.Watch:Disconnect();self.Watch=nil end
        self.WatchedItem=nil
        self.Visit=nil
        table.clear(self.Pending)
    end
    function Mode:_latency(player)
        local ok,ping=pcall(player.GetNetworkPing,player)
        return ok and bounded(ping*0.5,0,0,0.5) or 0
    end
    function Mode:_eyeOffset()
        local engine=self.Engine
        local inner=engine._context and engine._context.Inner
        local controller=inner and inner.CharacterController
        
        
        
        
        if controller and type(controller.IsCrouching)=="function" then
            local ok,crouching=pcall(controller.IsCrouching,controller)
            if ok then return Vector3.new(0,crouching and 0.25 or 1.75,0) end
        end
        return Vector3.new(0,1.75,0)
    end
    function Mode:_motion(target, now)
        local head=target.Head
        local current=head.Position
        local velocity=target.Root.AssemblyLinearVelocity
        if not vector(velocity) then velocity=Vector3.zero end
        local previous=self.Motion[target.Model]
        local warped=false
        if previous then
            local dt=now-previous.Time
            if dt>0 and dt<0.5 then
                local measured=(current-previous.Position)/dt
                local residual=(current-previous.Position-previous.Velocity*dt).Magnitude
                warped=residual>math.max(40,previous.Velocity.Magnitude*dt*3)
                if not warped and vector(measured) and measured.Magnitude>0.1 then
                    velocity=velocity.Magnitude<0.1 and measured or velocity*0.65+measured*0.35
                end
            end
        end
        if warped then self.Stats.Teleports+=1;velocity=Vector3.zero end
        self.Motion[target.Model]={Position=current,Velocity=velocity,Time=now}
        return velocity,warped
    end
    function Mode:_arcClear(plan, target, own)
        local world=self.Engine._visibility and self.Engine._visibility._worldInclude
        local params=world and world:GetMapParams()
        if not params then
            params=RaycastParams.new()
            params.FilterType=Enum.RaycastFilterType.Exclude
            params.FilterDescendantsInstances={target.Model,own,workspace.CurrentCamera}
            params.IgnoreWater=true
            params.RespectCanCollide=true
        end
        local previous=plan.Origin
        for i=1,8 do
            local t=plan.Time*i/8
            local point=plan.Origin+plan.Direction*plan.Speed*t+plan.Gravity*(0.5*t*t)
            local hit=workspace:Raycast(previous,point-previous,params)
            if hit and not hit.Instance:IsDescendantOf(target.Model) then return false end
            previous=point
        end
        return true
    end
    function Mode:_plan(item,target,pose,velocity,cfg,latency,own)
        local precision=Mode.Precision(target.Head.Position)
        local radius=math.min(target.Head.Size.X,target.Head.Size.Y,target.Head.Size.Z)*0.5
        if precision>radius*0.5 then return nil,"World precision is too low for head aiming" end
        local settings=cfg.Daggers or {}
        local eye=pose.Position+self:_eyeOffset()
        local speed=bounded(item.Info.ProjectileSpeed,300,1,10000)
        local gravity=Vector3.new(0,-workspace.Gravity*bounded(item.Info.ProjectileGravity,0.25,0,10),0)
        local plan,reason=Mode.Solve(eye,target.Head.Position,velocity,speed,gravity,latency,
            bounded(settings.MaxFlightMS,80,50,2000)/1000)
        if not plan then return nil,reason end
        if not self:_arcClear(plan,target,own) then return nil,"Head trajectory blocked" end
        plan.Eye=eye
        plan.Camera=Mode.Look(eye,plan.Offset)
        return plan
    end
    function Mode:_pose(item,target,velocity,cfg,latency,settle,own)
        local settings=cfg.Daggers or {}
        local precision=Mode.Precision(target.Head.Position)
        local near=settings.Placement=="NearHead"
        local distance=math.max(bounded(settings.Distance,10,6,40),precision*8)
        local predicted=target.Head.Position+velocity*(settle+latency)
        predicted=Vector3.new(predicted.X,math.max(predicted.Y,target.Head.Position.Y),predicted.Z)
        local eyeOffset=self:_eyeOffset()
        
        
        local points={Vector3.new(0,1,distance),Vector3.new(distance,1,0),
            Vector3.new(-distance,1,0),Vector3.new(0,1,-distance)}
        if near then
            points={}
            for _,direction in ipairs({Vector3.zAxis,Vector3.xAxis,-Vector3.xAxis,-Vector3.zAxis}) do
                points[#points+1]=Mode.NearOffset(item,target.Head,direction,settings.HeadClearance)
            end
        end
        local failure="No clear Daggers head intercept"
        for _,offset in ipairs(points) do
            local eye=predicted+offset
            local pose=Mode.Look(eye-eyeOffset,predicted-eye)
            if pose then
                
                
                local plan,reason=self:_plan(item,target,pose,velocity,cfg,latency+settle,own)
                if plan then return pose end
                failure=reason or failure
            end
        end
        return nil,failure
    end
    function Mode:_watch(item)
        if self.WatchedItem==item then return end
        if self.Watch then self.Watch:Disconnect() end
        self.Watch=nil;self.WatchedItem=item
        local signal=item.ProjectileShot
        if signal and type(signal.Connect)=="function" then
            local generation=self.Generation
            self.Watch=signal:Connect(function(sourcePart,visualModel)
                if generation~=self.Generation or self.WatchedItem~=item then return end
                if not sourcePart or typeof(sourcePart)~="Instance" or not sourcePart:IsA("BasePart") then return end
                for i,flight in ipairs(self.Pending) do
                    local elapsed=math.max(0,self.Engine._clock()-flight.Time)
                    local reach=math.max(16,flight.Plan.Speed*(elapsed+0.05))
                    if (sourcePart.Position-flight.Plan.Origin).Magnitude<=reach then
                        table.remove(self.Pending,i)
                        flight.Visit.Pending=math.max(0,(flight.Visit.Pending or 0)-1)
                        self.Stats.Launches+=1
                        self.Stats.LastLaunchSpeed=sourcePart.AssemblyLinearVelocity.Magnitude
                        return
                    end
                end
            end)
        end
    end
    function Mode:_shoot(visit, target, velocity, cfg, latency, own)
        local engine=self.Engine
        local item=visit.Item
        local plan,reason=self:_plan(item,target,visit.Pose,velocity,cfg,latency,own)
        if not plan then
            self.Stats.NoIntercept+=1;visit.ReleaseAt=engine._clock();visit.Finished=true
            self:_status(reason);return
        end
        local fighter=engine._api.FighterController.LocalFighter
        local generation=self.Generation
        local job={Fighter=fighter,Item=item,Active=true,Started=engine._clock()}
        self.Job=job
        self:_watch(item)
        job.Thread=task.spawn(function()
            local ok,problem=pcall(function()
                local function current()
                    return self.Job==job and self.Visit==visit and generation==self.Generation
                        and fighter.EquippedItem==item and target.Head.Parent and target.Humanoid.Health>0
                end
                if not current() then return end
                local original=fighter.GetCameraData
                job.PreviousCamera=rawget(fighter,"GetCameraData")
                local thread=coroutine.running()
                local function cameraData()
                    
                    
                    
                    
                    local eye=Mode.Look(plan.Eye,plan.Offset)
                    local surface=target.Head:GetClosestPointOnSurface(plan.Eye)
                    local movement=plan.Velocity
                    if (cfg.Daggers or {}).Placement~="NearHead"
                        and (cfg.Daggers or {}).MotionCompensation~=false and movement.Magnitude>3 then
                        local point=target.Head.CFrame:PointToObjectSpace(surface)
                        surface=target.Head.CFrame:PointToWorldSpace(Vector3.new(point.X,target.Head.Size.Y*0.3,point.Z))
                            +Vector3.new(movement.X*(plan.Time+plan.Latency),movement.Y*plan.Time,movement.Z*(plan.Time+plan.Latency))
                            -plan.Gravity*(0.5*plan.Time*plan.Time)
                    end
                    return {["\0"]=engine._api.Utility:EncodeCFrame(eye),
                        ["\1"]=engine._api.Utility:EncodeCFrame(Mode.Look(plan.Eye+plan.Direction*0.3,plan.Offset)),
                        ["\2"]=target.Head,
                        ["\3"]=engine._api.Utility:EncodeCFrame(target.Head.CFrame:ToObjectSpace(CFrame.new(surface)))}
                end
                job.Provider=function(selfFighter,...)
                    if job.Active and coroutine.running()==thread then return cameraData() end
                    return original(selfFighter,...)
                end
                rawset(fighter,"GetCameraData",job.Provider)
                local result=table.pack(item:StartShooting(false,nil))
                self:_releaseJob(job)
                if not current() then return end
                if result[1]~=true then
                    self.Stats.NativeDeclines+=1
                    visit.Next=engine._clock()+0.02
                    return
                end
                if (target.Head.Position-plan.Head).Magnitude>math.max(20,velocity.Magnitude*0.1) then
                    visit.Finished=true;visit.ReleaseAt=engine._clock();return
                end
                local action=result[2]
                if action~="StartShooting" and action~="StartReloading" then return end
                if action=="StartShooting" then
                    local latest,changed=self:_motion(target,engine._clock())
                    local refreshed,why=self:_plan(item,target,visit.Pose,latest,cfg,latency,own)
                    if changed or not refreshed then
                        visit.Finished=true;visit.ReleaseAt=engine._clock()
                        self:_status(why or "Target teleported during Daggers preparation")
                        return
                    end
                    plan=refreshed
                end
                local packet={}
                for i=3,result.n do packet[utf8.char(i-2)]=result[i] end
                if action=="StartShooting" then packet["\1"]=cameraData() end
                local id=read(item,"ObjectID")
                if id==nil then error("Missing Daggers ObjectID") end
                local flight={Time=engine._clock(),Plan=plan,Expires=engine._clock()+1,Visit=visit}
                if action=="StartShooting" then
                    self.Pending[#self.Pending+1]=flight
                    visit.Pending=(visit.Pending or 0)+1
                    job.Flight=flight
                end
                engine._features.WithShot(function()
                    
                    
                    engine._api.UseItemRemote.FireServer(engine._api.UseItemRemote,id,engine._sender:Enum(action),packet,nil)
                end)
                if action=="StartShooting" then
                    visit.Shots+=1
                    engine._tactics:RecordShot(item,target,read(item,"Ammo"))
                    self.Stats.Requests+=1
                    self.Stats.LastFlightMS=plan.Time*1000
                    engine._stats.Requests+=1
                    local cooldown=bounded(item.Info.ShootCooldown,0.6,1/240,5)
                    local burst=bounded(item.Info.BurstCooldown,0.1,1/240,5)
                    visit.Next=engine._clock()+(visit.Shots<2 and burst or cooldown)
                    visit.ReleaseAt=engine._clock()+visit.Window
                    visit.ObserveUntil=engine._clock()+math.max(0.35,visit.Window*2+0.1)
                    visit.ShotSteps=engine._transport:GetSimulationSteps()+2
                    if visit.Shots>=2 then visit.Finished=true end
                    engine._stats.LastShot={Time=engine._clock(),Target=target.Player.Name,
                        Health=target.Humanoid.Health,Requests=1,Part="Head"}
                else
                    engine._stats.ReloadRequests+=1
                    visit.Finished=true;visit.ReleaseAt=engine._clock()+visit.Window
                end
            end)
            self:_releaseJob(job)
            if self.Job==job then self.Job=nil end
            if not ok then
                local index=job.Flight and table.find(self.Pending,job.Flight)
                if index then table.remove(self.Pending,index);visit.Pending=math.max(0,(visit.Pending or 0)-1) end
                engine._stats.Errors+=1;engine._stats.LastError=tostring(problem)
                visit.Finished=true;visit.ReleaseAt=engine._clock()+visit.Window
                self:_status("Daggers action error: "..tostring(problem))
            end
        end)
    end
    function Mode:Tick(dt,cfg,native,player,state,environment,home)
        local e=self.Engine
        local now=e._clock()
        local item=native.EquippedItem
        e._item=item
        for i=#self.Pending,1,-1 do
            if now>=self.Pending[i].Expires then
                local old=table.remove(self.Pending,i)
                old.Visit.Pending=math.max(0,(old.Visit.Pending or 0)-1)
                self.Stats.Unconfirmed+=1
            end
        end
        local function cover(target)
            e._phase="idle"
            e:_idle(home,target,state.RootPart,cfg)
        end
        if not Mode.IsDaggers(item) then self:Reset();self:_status("Equip Daggers for Daggers mode");cover();return end
        local visit=self.Visit
        local target=visit and e:_eligible(visit.Target.Player,native,environment)
            or e:_selectTarget(native,environment,cfg,home.Position)
        e._target=target;e._lastTargetWorld=target and target.Root.Position
        if not target then self:Reset();self:_status("No eligible Daggers target");cover();return end
        if visit and (visit.Target.Model~=target.Model or visit.Item~=item) then self:Reset();visit=nil end
        local velocity,warped=self:_motion(target,now)
        if warped and visit then self:Reset();self:_status("Target teleported - reacquiring head");cover(target);return end
        if visit then
            e._phase=self.Job and "prepare" or (visit.Finished and "hold" or "daggers")
            e._transport:Park(visit.Pose,true)
            if self.Job then
                if now-self.Job.Started>0.8 then self:Reset();self:_status("Retrying native Daggers action");cover(target) end
                return
            end
            if visit.Finished then
                if now<(visit.ReleaseAt or now)
                    or ((visit.Pending or 0)>0 and now<(visit.ObserveUntil or 0))
                    or e._transport:GetSimulationSteps()<(visit.ShotSteps or 0) then
                    self:_status("Waiting for Daggers launch");return
                end
                local lost=math.max(0,visit.Health-target.Humanoid.Health)
                self.Stats.DamageObserved+=lost
                e._stats.Bursts+=1
                self.Visit=nil
                self:_status("Returning to cover after Daggers burst")
                cover(target);return
            end
        end
        if e:_ammoState(item)~="Ready" or e:_reloadBusy(item) then
            if visit and visit.Shots>0 and now<(visit.ReleaseAt or 0) then self:_status("Waiting for Daggers launch");return end
            self.Visit=nil
            e:_requestReload(native,item)
            self:_status("Reloading Daggers");cover(target);return
        end
        if not visit then
            if (tonumber(item._shoot_cooldown) or 0)>tick() or (tonumber(item._equip_cooldown) or 0)>tick() then
                self:_status("Daggers cooldown");cover(target);return
            end
            local oneWay=self:_latency(player)
            local window=math.max(e:_replicationWindow(player),oneWay*2+2/60)
            local settle=math.max(window,bounded((cfg.Daggers or {}).SettleMS,200,50,750)/1000)
            local latency=oneWay*2+bounded((cfg.Daggers or {}).ExtraLeadMS,0,0,250)/1000
            local pose,reason=self:_pose(item,target,velocity,cfg,latency,settle,state.Model)
            if not pose then self.Stats.NoIntercept+=1;self:_status(reason or "No clear Daggers head intercept");cover(target);return end
            visit={Target=target,Item=item,Pose=pose,Ready=now+settle,Steps=e._transport:GetSimulationSteps()+2,
                Shots=0,Next=now,Window=window,Latency=latency,Health=target.Humanoid.Health}
            self.Visit=visit
        end
        e._transport:Park(visit.Pose,true)
        if now<visit.Ready or e._transport:GetSimulationSteps()<visit.Steps then
            e._phase="settle";self:_status("Synchronizing Daggers launch position");return
        end
        e._phase="daggers"
        if now>=visit.Next and (tonumber(item._shoot_cooldown) or 0)<=tick() then
            self:_shoot(visit,target,velocity,cfg,visit.Latency,state.Model)
        end
        self:_status("Tracking head with Daggers")
    end
    Mode.ValidVector=vector
    return Mode
end)()


local absenseNativeRage = (function()
    local Mode={}
    Mode.__index=Mode
    local function read(item,key)
        local ok,result=pcall(item.Get,item,key)
        if ok and result~=nil then return result end
        return item.Data and item.Data[key]
    end
    local function number(value,fallback,minimum,maximum)
        value=tonumber(value)
        if not value or value~=value or math.abs(value)==math.huge then value=fallback end
        return math.clamp(value,minimum,maximum)
    end
    function Mode.Kind(item)
        if not item or not item.Info then return nil end
        if item.Name=="Knife" then return "Knife" end
        if item.Name=="Gunblade" then
            return read(item,"Mode")=="Blade" and "GunbladeBlade" or "GunbladeGun"
        end
        return nil
    end
    function Mode.Look(origin,direction)
        local scale=math.max(math.abs(direction.X),math.abs(direction.Y),math.abs(direction.Z))
        if scale<1e-9 then return nil end
        local d=direction/scale
        local up=math.abs(d.Unit.Y)>.99 and Vector3.zAxis or Vector3.yAxis
        return CFrame.new(origin)*CFrame.lookAt(Vector3.zero,d,up)
    end
    function Mode.new(engine)
        return setmetatable({Engine=engine,Generation=0,NextAttack=0,
            Stats={Requests=0,NativeDeclines=0,Errors=0,Contacts=0,Cancelled=0}},Mode)
    end
    function Mode:_status(message)
        self.Stats.Status=message
        self.Engine._stats.Status=message
    end
    function Mode:_release(job)
        if not job then return end
        job.Active=false
        if rawget(job.Fighter,"GetCameraData")==job.Provider then
            rawset(job.Fighter,"GetCameraData",job.Previous)
        end
    end
    function Mode:Reset()
        self.Generation+=1
        self.Engine._transport:CancelOneFrame()
        local job=self.Job
        self.Job=nil
        self:_release(job)
        if job and job.Thread and job.Thread~=coroutine.running() then pcall(task.cancel,job.Thread) end
        self.Visit=nil
        self.Item=nil
        self.KindName=nil
        self.CoverReady=nil
    end
    function Mode:_eyeOffset()
        local inner=self.Engine._context.Inner
        local controller=inner and inner.CharacterController
        if controller and controller.IsCrouching then
            local ok,crouch=pcall(controller.IsCrouching,controller)
            if ok then return Vector3.new(0,crouch and .25 or 1.75,0) end
        end
        return Vector3.new(0,1.75,0)
    end
    function Mode:_cover(cfg,home,forceVoid)
        local e=self.Engine
        forceVoid=forceVoid or self.KindName=="Knife"
        local pose
        if forceVoid then
            local settings=cfg.VoidSpam or {}
            self.VoidConfig=self.VoidConfig or {VoidSpam={Enabled=true}}
            self.VoidConfig.VoidSpam.MinDistance=number(settings.MinDistance,100000,10000,1000000)
            self.VoidConfig.VoidSpam.IntervalMS=number(settings.IntervalMS,1,1,1000)
            pose=e._features:VoidPose(self.VoidConfig)
        else
            pose=e._features:IdlePose(e._target and e:_asTarget(e._target),e._transport._root,cfg)
        end
        pose=pose or home
        e._transport:Park(pose,true)
        self.CoverPose=pose
        return pose
    end
    function Mode:_contact(target,item,kind)
        local reach=kind=="Knife" and item.Info.HeavyAttackReach or item.Info.BladeReach
        local distance=math.max(2,number(reach,7,2,30)-.75)
        local root=target.Root
        local scale=math.max(math.abs(root.Position.X),math.abs(root.Position.Y),math.abs(root.Position.Z),1)
        if 2^(math.floor(math.log(scale)/math.log(2))-23)>distance*.25 then return nil end
        local direction=Vector3.new(-root.CFrame.LookVector.X,0,-root.CFrame.LookVector.Z)
        if direction.Magnitude<.01 then direction=Vector3.zAxis end
        local eye=target.Head.Position+direction.Unit*distance
        local position=eye-self:_eyeOffset()
        local pose=CFrame.new(position)*CFrame.lookAt(Vector3.zero,-direction.Unit)
        return self.Engine._tactics:Orient(pose,target,self.Engine:_settings())
    end
    function Mode:_camera(origin,target)
        local e=self.Engine
        local head=self.KindName~="GunbladeGun" and (target.Body or target.Head) or target.Head
        local point=head:GetClosestPointOnSurface(origin)
        local look=Mode.Look(origin,point-origin)
        if not look then error("Invalid native attack direction") end
        local encode=e._api.Utility.EncodeCFrame
        local offset=head.CFrame:ToObjectSpace(CFrame.new(point))
        local raw={["\0"]=look,["\1"]=look,["\2"]=head,["\3"]=offset}
        return {["\0"]=encode(e._api.Utility,look),["\1"]=encode(e._api.Utility,look),
            ["\2"]=head,["\3"]=encode(e._api.Utility,offset)},raw
    end
    function Mode:_queueContact(target,item,kind,returnPose,generation)
        local e=self.Engine
        local queued=e._transport:ArmOneFrame(function()
            return self:_contact(target,item,kind)
        end,returnPose,function()
            local f=e._api.FighterController.LocalFighter
            return generation==self.Generation and e._enabled and f and f.EquippedItem==item
                and target.Head.Parent~=nil and target.Humanoid.Health>0
        end,function(frames,elapsed)
            if generation~=self.Generation then return end
            self.Stats.Contacts+=1
            self.Stats.LastContactFrames=frames
            self.Stats.LastContactMS=elapsed*1000
            self.Stats.LastReturnAt=e._clock()
            self:_status("Returned to void after one contact frame")
        end)
        if not queued then self.Stats.Cancelled+=1 end
    end
    function Mode:_attack(item,target,kind,origin,returnPose,postContact)
        local e=self.Engine
        local fighter=e._api.FighterController.LocalFighter
        local generation=self.Generation
        local job={Fighter=fighter,Active=true,Started=e._clock()}
        self.Job=job
        job.Thread=task.spawn(function()
            local identity
            if type(getthreadidentity)=="function" and type(setthreadidentity)=="function" then
                local known,value=pcall(getthreadidentity)
                if known then identity=value;pcall(setthreadidentity,2) end
            end
            local ok,problem=xpcall(function()
                local function current()
                    return self.Job==job and self.Generation==generation and e._enabled
                        and fighter==e._api.FighterController.LocalFighter and fighter.EquippedItem==item
                        and target.Head.Parent~=nil and target.Humanoid.Health>0
                end
                if not current() or not e:_eligible(target.Player,fighter,e._environment) then return end
                local inherited=fighter.GetCameraData
                job.Previous=rawget(fighter,"GetCameraData")
                local owner=coroutine.running()
                job.Provider=function(selfFighter,...)
                    if job.Active and coroutine.running()==owner then
                        local encoded,raw=self:_camera(origin,target)
                        if select(3,...)==true then return raw end
                        return encoded,raw
                    end
                    return inherited(selfFighter,...)
                end
                rawset(fighter,"GetCameraData",job.Provider)
                local beforeAmmo=read(item,"Ammo")
                local result
                if kind=="Knife" then result=table.pack(item:StartAiming(false,nil))
                else result=table.pack(item:StartShooting(false,nil)) end
                self:_release(job)
                if not current() or not e:_eligible(target.Player,fighter,e._environment) then return end
                if result[1]~=true then
                    self.Stats.NativeDeclines+=1
                    self.NextAttack=e._clock()+.03
                    self:_status("Waiting for native weapon cooldown")
                    return
                end
                local action=result[2]
                if action~="StartShooting" and action~="StartAiming" then error("Unexpected native attack action") end
                local packet={}
                for index=3,result.n do packet[utf8.char(index-2)]=result[index] end
                local id=read(item,"ObjectID")
                if not id then error("Missing native weapon identity") end
                e._features.WithShot(function()
                    e._api.UseItemRemote.FireServer(e._api.UseItemRemote,id,e._sender:Enum(action),packet,nil)
                end)
                self.Stats.Requests+=1
                e._tactics:RecordShot(item,target,beforeAmmo)
                self.Stats.LastAction=action
                self.Stats.LastAttackAt=e._clock()
                self.Stats.LastAttackOrigin=origin
                self.Stats.LastCharacterOrigin=e._transport._root.Position
                self.Stats.LastAttackFromVoid=postContact
                e._stats.Requests+=1
                e._stats.LastShot={Time=e._clock(),Target=target.Player.Name,Health=target.Humanoid.Health,Requests=1,
                    Part=kind=="GunbladeGun" and "Head" or "Body"}
                local duration=kind=="Knife" and item.Info.HeavyAttackCooldown
                    or kind=="GunbladeBlade" and item.Info.BladeCooldown or item.Info.ShootCooldown
                self.NextAttack=e._clock()+number(duration,.75,1/60,5)
                if postContact then
                    self:_queueContact(target,item,kind,returnPose,generation)
                    self:_status("Attack sent from void; contact queued for next frame")
                else
                    self.Visit.Fired=true
                    self.Visit.ReleaseAt=e._clock()+self.Visit.Window
                    self.Visit.ReleaseStep=e._transport:GetSimulationSteps()+1
                    self:_status("Native "..item.Name.." attack sent")
                end
            end,debug.traceback)
            self:_release(job)
            if identity~=nil then pcall(setthreadidentity,identity) end
            if self.Job==job then self.Job=nil end
            if not ok then
                self.Stats.Errors+=1
                e._stats.Errors+=1
                e._stats.LastError=tostring(problem)
                self.NextAttack=e._clock()+.25
                self.Visit=nil
                self:_status("Native attack failed: "..tostring(problem))
            end
        end)
    end
    function Mode:Tick(dt,cfg,native,player,state,environment,home,mode)
        local e=self.Engine
        local item=native.EquippedItem
        local kind=Mode.Kind(item)
        if (mode=="Knife" and kind~="Knife") or (mode=="Gunblade" and not (kind and kind:find("Gunblade",1,true))) then
            self:Reset()
            self:_status("Equip "..mode.." for this mode")
            self:_cover(cfg,home,mode=="Knife")
            return
        end
        if item~=self.Item or kind~=self.KindName then
            self:Reset();self.Item=item;self.KindName=kind;self.NextAttack=0
        end
        self.Stats.WeaponMode=kind
        e._item=item
        local now=e._clock()
        local target=e:_selectTarget(native,environment,cfg,home.Position)
        e._target=target;e._lastTargetWorld=target and target.Root.Position
        if not target then
            if self.Job or self.Visit then self:Reset() end
            self:_cover(cfg,home,kind=="Knife")
            self:_status("No eligible target");return
        end
        if self.Job then
            if now-self.Job.Started>.8 then self:Reset();self:_status("Native action timed out") end
            return
        end
        if kind=="Knife" and (cfg.Knife or {}).Timing~="BeforeAttack" then
            e._phase="knife_void"
            if e._transport:HasOneFrame() then return end
            local cover=self:_cover(cfg,home,true)
            self.CoverReady=self.CoverReady or now+e:_replicationWindow(player)
            if e._tactics:Waiting(item) then self:_status("Waiting for Knife hit confirmation");return end
            if now<self.CoverReady or now<self.NextAttack or (tonumber(item._attack_cooldown) or 0)>tick() then return end
            local contact=self:_contact(target,item,kind)
            if not contact then self:_status("Target position lacks melee precision");return end
            self:_attack(item,target,kind,contact.Position+self:_eyeOffset(),cover,true)
            return
        end
        local visit=self.Visit
        if visit and (visit.Item~=item or visit.Target.Model~=target.Model) then self.Visit=nil;visit=nil end
        if visit and not e._planner:Follow(visit,target,target.Head) then
            self.Visit=nil;self:_cover(cfg,home,false);self:_status("Target teleported; repositioning");return
        end
        if visit and visit.Fired then
            e._phase="hold"
            e._transport:Park(visit.Pose,true)
            if now>=visit.ReleaseAt and e._transport:GetSimulationSteps()>=visit.ReleaseStep then
                self.Visit=nil;e._stats.Bursts+=1;self:_cover(cfg,home,false)
            end
            return
        end
        if kind=="GunbladeGun" and e:_ammoState(item)~="Ready" then
            self.Visit=nil;self:_cover(cfg,home,false)
            if e:_ammoState(item)=="Reload" then e:_requestReload(native,item) end
            self:_status("Gunblade gun mode has no ammunition");return
        end
        if not visit and e._tactics:Waiting(item) then
            self:_cover(cfg,home,false);self:_status("Waiting for hit confirmation");return
        end
        local nativeCooldown=kind=="GunbladeBlade" and item._blade_cooldown
            or kind=="Knife" and item._attack_cooldown or item._shoot_cooldown
        if now<self.NextAttack or (tonumber(nativeCooldown) or 0)>tick() or (tonumber(item._transition_cooldown) or 0)>tick()
            or (tonumber(item._equip_cooldown) or 0)>tick() then
            self:_cover(cfg,home,false);self:_status("Gunblade cooldown");return
        end
        if not visit then
            local pose=(kind=="GunbladeBlade" or kind=="Knife") and self:_contact(target,item,kind)
                or e:_position(target,target.Head,state.RootPart,cfg,false)
            if not pose then self:_cover(cfg,home,false);self:_status("No clear Gunblade position");return end
            local window=e:_replicationWindow(player)
            visit={Item=item,Target=target,Pose=pose,Ready=now+window,Window=window,
                Step=e._transport:GetSimulationSteps()+2}
            e._planner:Prepare(visit,target,target.Head,cfg)
            self.Visit=visit
        end
        e._phase="settle"
        e._transport:Park(visit.Pose,true)
        if now<visit.Ready or e._transport:GetSimulationSteps()<visit.Step then
            self:_status("Synchronizing Gunblade position");return
        end
        self:_attack(item,target,kind,visit.Pose.Position+self:_eyeOffset(),nil,false)
    end
    return Mode
end)()




local absenseRageTactics = (function()
    local Tactics = {}
    Tactics.__index = Tactics

    local bypassDeflection = {
        ["Battle Axe"] = true, Bow = true, Chainsaw = true, Crossbow = true,
        Daggers = true, Exogun = true, Fists = true, Flamethrower = true,
        ["Grenade Launcher"] = true, Katana = true, Knife = true, Maul = true,
        RPG = true, ["Riot Shield"] = true, Scythe = true, Slingshot = true,
        Spear = true, Spray = true, Trowel = true,
    }
    local utilityWeapons = {
        Flashbang = true, ["Freeze Ray"] = true, Grappler = true, Grenade = true,
        ["Jump Pad"] = true, Medkit = true, Molotov = true, Satchel = true,
        ["Smoke Grenade"] = true, ["Subspace Tripmine"] = true,
        ["War Horn"] = true, Warper = true, Warpstone = true,
    }
    local pauseMaps = { Bridge = true, Museum = true, Studio = true }
    local function read(object, key)
        if not object then return nil end
        if type(object.Get) == "function" then
            local ok, value = pcall(object.Get, object, key)
            if ok and value ~= nil then return value end
        end
        return object.Data and object.Data[key] or object[key]
    end
    local function number(value, fallback, low, high)
        value = tonumber(value)
        if not value or value ~= value or math.abs(value) == math.huge then value = fallback end
        return math.clamp(value, low, high)
    end
    local function weakKeys() return setmetatable({}, { __mode = "k" }) end

    function Tactics.new(engine, dependencies)
        local self = setmetatable({
            Engine = engine, World = dependencies.World or workspace,
            Collection = dependencies.CollectionService or game:GetService("CollectionService"),
            Mines = {}, MineConnections = {}, Immunity = weakKeys(), Shields = weakKeys(),
            Pending = weakKeys(), ShieldNames = { ["Riot Shield"] = true },
            Stats = { ConfirmedHits = 0, ObservedDamage = 0, UnconfirmedShots = 0,
                AmmoAcknowledged = 0, AvoidedMines = 0 },
        }, Tactics)
        self.RayParams = RaycastParams.new()
        self.RayParams.FilterType = Enum.RaycastFilterType.Exclude
        self.RayParams.IgnoreWater = true
        self.RayParams.RespectCanCollide = true
        local cosmetics = engine._api.CosmeticLibrary
        for name, entry in pairs(cosmetics and cosmetics.Cosmetics or {}) do
            if type(entry) == "table" and entry.Type == "Skin" and entry.ItemName == "Riot Shield" then self.ShieldNames[name] = true end
        end
        if dependencies.Replicator then
            self.HitBinding = dependencies.Replicator:Reserve({ "DamageNumberEffect" })
            self.HitBinding:SetHandler(function(packet)
                local ok, problem = pcall(self.OnHit, self, packet)
                if not ok then self.Stats.LastError = tostring(problem) end
            end)
        end
        return self
    end

    function Tactics.IsCombatItem(item)
        return item and item.Info and not utilityWeapons[item.Name]
            and (item.Info.Type == "Gun" or item.Info.Type == "Melee")
    end

    function Tactics:Eligible(target, native, item, cfg)
        local now = self.Engine._clock()
        if read(native.Entity, "IsInvincible") == true
            or target.Model:FindFirstChildOfClass("ForceField") then
            self.Immunity[target.Model] = now + 0.5
            return false
        end
        if now < (self.Immunity[target.Model] or 0) then return false end
        if (cfg.Safety or {}).ShieldAware == false then return true end
        local equipped = native.EquippedItem
        local deflecting = equipped and (read(equipped, "IsDeflecting") == true
            or (equipped.Name == "Katana" and (tonumber(read(equipped, "FOVOffset")) or 0) > 0))
        if deflecting and not (item and bypassDeflection[item.Name]) then return false end
        return true
    end

    function Tactics:ShieldBelow(target, cfg)
        if (cfg.Safety or {}).ShieldAware == false then return nil end
        local now = self.Engine._clock()
        local cached = self.Shields[target.Model]
        if cached and now < cached.Until then return cached.Below end
        local native = target.Native
        local item = native and native.EquippedItem
        local equipped = item and item.Name == "Riot Shield"
        local carried = false
        if not equipped then
            for _, child in ipairs(target.Model:GetChildren()) do
                if child:IsA("Model") and self.ShieldNames[child.Name] then equipped = true; break end
            end
        end
        if not equipped then
            for _, entry in pairs(native and native.Items or {}) do
                if entry.Name == "Riot Shield" then carried = true; break end
            end
        end
        local below
        if equipped or carried then
            local rotation = read(native, "CameraRotation") or read(native, "_camera_rotation")
            local head = target.Model:FindFirstChild("Head") or target.Head
            local pitch = typeof(rotation) == "Vector2" and math.deg(rotation.X) % 360
                or math.deg(math.asin(math.clamp(head.CFrame.LookVector.Y, -1, 1))) % 360
            if equipped then below = pitch > 22 and pitch < 91
            else below = not ((pitch > 315 and pitch < 360) or (pitch > 0 and pitch < 91)) end
        end
        self.Shields[target.Model] = { Until = now + 0.1, Below = below }
        return below
    end

    function Tactics:Orient(pose, target, cfg)
        if not pose or not target or (cfg.Safety or {}).ShieldAware == false then return pose end
        local native = self.Engine._api.FighterController.LocalFighter
        for _, item in pairs(native and native.Items or {}) do
            if item.Name == "Riot Shield" then
                local facing = target.Root.Position - pose.Position
                if native.EquippedItem ~= item then facing = -facing end
                if facing.Magnitude > 0.001 then
                    return CFrame.lookAt(pose.Position, pose.Position + facing,
                        math.abs(facing.Unit.Y) > 0.99 and Vector3.zAxis or Vector3.yAxis)
                end
            end
        end
        return pose
    end

    function Tactics:_ground(position, character, targetModel)
        local ignored = { character, targetModel }
        for _, player in ipairs(self.Engine._services.Players:GetPlayers()) do
            if player.Character then ignored[#ignored + 1] = player.Character end
        end
        
        local filter = {}
        for _, instance in pairs(ignored) do if instance then filter[#filter + 1] = instance end end
        self.RayParams.FilterDescendantsInstances = filter
        return self.World:Raycast(position + Vector3.yAxis * 2, -Vector3.yAxis * 502, self.RayParams)
    end

    function Tactics:Underground(home, character)
        local now = self.Engine._clock()
        if self.GroundHome and (self.GroundHome - home.Position).Magnitude < 2
            and now < (self.GroundUntil or 0) then return self.GroundPose end
        self.GroundHome, self.GroundUntil = home.Position, now + 0.25
        local hit = self:_ground(home.Position, character)
        self.GroundPose = hit and CFrame.new(home.Position.X, hit.Position.Y - 1.5, home.Position.Z)
            * CFrame.Angles(math.pi / 2, 0, 0) or nil
        return self.GroundPose
    end

    function Tactics:Position(target, part, root, cfg, melee)
        local strategy = (cfg.Engine or {}).Positioning or "Adaptive"
        if strategy == "Adaptive" or melee then return nil, false end
        local pose
        if strategy == "Inside" then
            pose = target.Root.CFrame * CFrame.new(0, -0.05, 0)
        elseif strategy == "Hide" then
            local position = target.Root.Position
            local hit = self:_ground(position, root.Parent, target.Model)
            local y = math.max(position.Y - 7.99, hit and hit.Position.Y - 1.5 or -math.huge)
            pose = CFrame.new(position.X, y, position.Z) * CFrame.Angles(math.pi / 2, 0, 0)
        elseif strategy == "Underground" then
            local home = self.Engine._transport:GetClientCFrame()
            pose = home and self:Underground(home, root.Parent)
            if pose and (part.Position - pose.Position).Magnitude > 100 then return nil, true end
        else return nil, false end
        if not pose then return nil, true end
        local eye = pose.Position + Vector3.new(0, 3, 0)
        if not self.Engine._features:ManipulateOrigin(eye, part, cfg, self.Engine._visibility) then return nil, true end
        return self:Orient(self.Engine._features:OrientPose(pose, cfg), target, cfg), true
    end

    function Tactics:OnHit(packet)
        if packet.EnumName ~= "DamageNumberEffect" then return end
        local inner = self.Engine._context.Inner
        if not inner or packet.ObjectId ~= inner.FighterState.ObjectId then return end
        local part = packet.Args and packet.Args[1]
        if typeof(part) ~= "Instance" then return end
        local now = self.Engine._clock()
        for item, shot in pairs(self.Pending) do
            if part:IsDescendantOf(shot.Model) or part == shot.Model then
                self.Stats.ConfirmedHits += 1
                self.Stats.LastHitAt = now
                self.Stats.LastDamage = tonumber(packet.Args[2]) or 0
                self.Pending[item] = nil
                break
            end
        end
    end

    function Tactics:RecordShot(item, target, ammo)
        local cfg = self.Engine:_settings()
        if (cfg.Engine or {}).ConfirmHits == false then return end
        local previous = self.Pending[item]
        if previous and previous.Model == target.Model then return end
        local now = self.Engine._clock()
        local ping = self.Engine:_replicationWindow(self.Engine._services.Players.LocalPlayer)
        self.Pending[item] = { Model = target.Model, Humanoid = target.Humanoid,
            Health = target.Humanoid.Health, Ammo = ammo, At = now,
            Deadline = now + math.clamp(ping + 0.2, 0.25, 0.9) }
    end

    function Tactics:_observeShots(now)
        for item, shot in pairs(self.Pending) do
            local health = shot.Humanoid.Parent and shot.Humanoid.Health
            local ammo = tonumber(read(item, "Ammo"))
            if not health or not shot.Model.Parent then
                self.Pending[item] = nil
            elseif health < shot.Health then
                
                
                self.Stats.ObservedDamage += shot.Health - health
                self.Pending[item] = nil
            elseif item.Name == "Sniper" and ammo and type(shot.Ammo) == "number" and ammo < shot.Ammo then
                self.Stats.AmmoAcknowledged += 1
                self.Pending[item] = nil
            elseif now >= shot.Deadline then
                self.Stats.UnconfirmedShots += 1
                self.Pending[item] = nil
                self.Engine._nextShot[item] = math.min(self.Engine._nextShot[item] or now, now)
            end
        end
    end

    function Tactics:Waiting(item)
        local pending = item and self.Pending[item]
        return item and (item.Name == "Knife" or item.Name == "Sniper") and pending ~= nil
    end

    function Tactics:TrackWeapon(item, now)
        if item ~= self.Item then
            self.Item = item
            self.Pending = weakKeys()
            self.EquipUntil = now + math.clamp(self.Engine:_replicationWindow(
                self.Engine._services.Players.LocalPlayer) + 0.1, 0.15, 0.5)
            return true
        end
        return false
    end

    function Tactics:_bindMines()
        if self.MineBound then return end
        self.MineBound = true
        local function add(mine) self.Mines[mine] = self.Engine._clock() end
        self.MineConnections[1] = self.Collection:GetInstanceAddedSignal("SubspaceTripmine"):Connect(add)
        self.MineConnections[2] = self.Collection:GetInstanceRemovedSignal("SubspaceTripmine"):Connect(function(mine)
            self.Mines[mine] = nil
        end)
        for _, mine in ipairs(self.Collection:GetTagged("SubspaceTripmine")) do add(mine) end
    end

    function Tactics:_releaseMines()
        for _, connection in ipairs(self.MineConnections) do connection:Disconnect() end
        table.clear(self.MineConnections)
        table.clear(self.Mines)
        self.MineBound, self.MineThreat, self.MineScanAt, self.MinePaused = false, nil, nil, false
    end

    function Tactics:_mines(native, environment, home, now)
        self:_bindMines()
        if now < (self.MineScanAt or 0) then return self.MineThreat end
        self.MineScanAt, self.MineThreat = now + 0.1, false
        local players = self.Engine._services.Players
        local localPlayer = players.LocalPlayer
        local ownTeam = read(native, "TeamID") or localPlayer:GetAttribute("TeamID")
        for mine, addedAt in pairs(self.Mines) do
            if not mine.Parent then self.Mines[mine] = nil; continue end
            local ownerId, team = mine:GetAttribute("PlacedByUserID"), mine:GetAttribute("TeamID")
            if ownerId == localPlayer.UserId or (team ~= nil and ownTeam ~= nil and team == ownTeam) then continue end
            local mineEnvironment = mine:GetAttribute("EnvironmentID")
            if mineEnvironment == nil and ownerId then
                local owner = players:GetPlayerByUserId(ownerId)
                local fighter = owner and (self.Engine._api.FighterController._player_to_fighter or {})[owner]
                mineEnvironment = read(fighter, "EnvironmentID") or (owner and owner:GetAttribute("EnvironmentID"))
            end
            if mineEnvironment ~= nil and mineEnvironment ~= environment then continue end
            local hitbox = mine:FindFirstChild("Hitbox")
            if not hitbox or not hitbox:IsA("BasePart") then continue end
            if mineEnvironment == nil and (hitbox.Position - home.Position).Magnitude > 2000 then continue end
            local armedAt = addedAt + number(mine:GetAttribute("HitboxDelay"), 0, 0, 30)
            if now >= armedAt and now < armedAt + 4 then
                self.MineThreat = true
            end
        end
        return self.MineThreat
    end

    function Tactics:_healthLead(native, environment, now)
        if now < (self.HealthScanAt or 0) then return self.HealthLead end
        self.HealthScanAt = now + 0.2
        local players = self.Engine._services.Players
        local localPlayer = players.LocalPlayer
        local team = read(native, "TeamID") or localPlayer:GetAttribute("TeamID")
        local own, enemy = 0, 0
        for _, player in ipairs(players:GetPlayers()) do
            local fighter = (self.Engine._api.FighterController._player_to_fighter or {})[player]
            if player == localPlayer then fighter = native end
            local env = read(fighter, "EnvironmentID") or (fighter and read(fighter.Entity, "EnvironmentID"))
                or player:GetAttribute("EnvironmentID")
            if env ~= environment then continue end
            local humanoid = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
            if not humanoid or humanoid.Health <= 0 then continue end
            local other = read(fighter, "TeamID") or player:GetAttribute("TeamID")
            local ally = player == localPlayer or (team ~= nil and other ~= nil and team == other)
                or (team == nil and other == nil and localPlayer.Team ~= nil and localPlayer.Team == player.Team)
            if ally then own += humanoid.Health else enemy += humanoid.Health end
        end
        self.Stats.TeamHealth, self.Stats.EnemyHealth = own, enemy
        self.HealthLead = enemy > 0 and own > enemy
        return self.HealthLead
    end

    function Tactics:_activePauseMap(environment)
        
        local roots = self.Collection:GetTagged("RaycastWhitelist" .. tostring(environment or ""))
        for _, root in ipairs(roots) do
            local node = root
            while node and node ~= self.World do
                if pauseMaps[node.Name] then return node.Name end
                node = node.Parent
            end
        end
        for name in pairs(pauseMaps) do
            local map = self.World:FindFirstChild(name)
            if map and map:GetAttribute("EnvironmentID") == environment then return name end
        end
        return nil
    end

    function Tactics:Update(cfg, native, environment, home, now)
        self.VoidPaused = false
        local confirm = (cfg.Engine or {}).ConfirmHits ~= false
        if self.HitBinding and self.HitBindingEnabled ~= confirm then
            self.HitBinding:SetEnabled(confirm)
            self.HitBindingEnabled = confirm
        end
        if not confirm then table.clear(self.Pending) end
        self:_observeShots(now)
        local safety = cfg.Safety or {}
        if safety.AvoidTripmines == false and self.MineBound then self:_releaseMines() end
        if safety.AvoidTripmines ~= false and self:_mines(native, environment, home, now) then
            if not self.MinePaused then self.Stats.AvoidedMines += 1 end
            self.MinePaused = true
            return "Waiting for hostile tripmine"
        end
        self.MinePaused = false
        if (safety.HealthLead == true or cfg.UtilizeHealthLead == true) and self:_healthLead(native, environment, now) then
            return "Protecting team health lead"
        end
        if safety.VoidPauses ~= false and cfg.VoidSpam and cfg.VoidSpam.Enabled then
            if now >= (self.MapScanAt or 0) or self.MapEnvironment ~= environment then
                self.MapScanAt, self.PauseMap = now + 2, nil
                self.MapEnvironment = environment
                self.PauseMap = self:_activePauseMap(environment)
            end
            if self.PauseMap then
                self.CycleStart = self.CycleStart or now
                self.VoidPaused = (now - self.CycleStart) % 3 >= 2
                if self.VoidPaused then return "Pausing void movement on " .. self.PauseMap end
            end
        else
            self.CycleStart = nil
        end
        self.VoidPaused = false
        return nil
    end

    function Tactics:IdlePose(home, root, cfg, retreat)
        if self.VoidPaused then return self:Underground(home, root.Parent) or home end
        if retreat then
            local spam = cfg.VoidSpam or {}
            self.RetreatConfig = self.RetreatConfig or { VoidSpam = { Enabled = true } }
            self.RetreatConfig.VoidSpam.MinDistance = number(spam.MinDistance, 100000, 10000, 1000000)
            self.RetreatConfig.VoidSpam.IntervalMS = number(spam.IntervalMS, 1, 1, 1000)
            return self.Engine._features:VoidPose(self.RetreatConfig)
        end
        if (cfg.Engine or {}).Positioning == "Underground" and not (cfg.VoidSpam and cfg.VoidSpam.Enabled) then
            return self:Underground(home, root.Parent) or home
        end
        return nil
    end

    function Tactics:Reset()
        if self.HitBinding then self.HitBinding:SetEnabled(false) end
        self.HitBindingEnabled = false
        self:_releaseMines()
        table.clear(self.Pending)
        table.clear(self.Immunity)
        table.clear(self.Shields)
        self.MineBound, self.Item, self.EquipUntil = false, nil, nil
        self.MineThreat, self.MineScanAt, self.HealthScanAt, self.HealthLead = nil, nil, nil, nil
        self.MinePaused = false
        self.CycleStart, self.VoidPaused, self.MapScanAt, self.PauseMap, self.MapEnvironment = nil, false, nil, nil, nil
        self.GroundHome, self.GroundPose, self.GroundUntil = nil, nil, nil
    end

    function Tactics:Destroy()
        self:Reset()
        if self.HitBinding then self.HitBinding:Destroy(); self.HitBinding = nil end
    end
    return Tactics
end)()



local absenseRagePlanner = (function()
    local Planner = {}
    Planner.__index = Planner
    local gunCooldowns = { "_shoot_cooldown", "_equip_cooldown", "_transition_cooldown" }
    local meleeCooldowns = { "_attack_cooldown", "_equip_cooldown", "_transition_cooldown" }

    local function number(value, fallback, low, high)
        value = tonumber(value)
        if not value or value ~= value or math.abs(value) == math.huge then value = fallback end
        return math.clamp(value, low, high)
    end

    local function read(object, key)
        if not object then return nil end
        if type(object.Get) == "function" then
            local ok, result = pcall(object.Get, object, key)
            if ok and result ~= nil then return result end
        end
        return object.Data and object.Data[key] or object[key]
    end

    local function vector(position)
        return typeof(position) == "Vector3" and position.X == position.X
            and position.Y == position.Y and position.Z == position.Z
            and math.max(math.abs(position.X), math.abs(position.Y), math.abs(position.Z)) < math.huge
    end

    function Planner.new(engine)
        return setmetatable({
            Engine = engine, Last = setmetatable({}, { __mode = "k" }),
            Unsafe = setmetatable({}, { __mode = "k" }),
            Stats = { Plans = 0, CandidateChecks = 0, ExposureRays = 0,
                DamageRetreats = 0, TargetResets = 0 },
        }, Planner)
    end

    function Planner:_threats(target, now)
        if self.ThreatTarget == target.Model and now < (self.ThreatAt or 0) then return end
        self.ThreatTarget, self.ThreatAt = target.Model, now + 0.1
        self.Blades, self.Watchers = {}, {}
        local engine = self.Engine
        local players = engine._services.Players
        local localPlayer = players.LocalPlayer
        local ownTeam = localPlayer:GetAttribute("TeamID")
        local candidates = {}
        for _, player in ipairs(players:GetPlayers()) do
            if player == localPlayer then continue end
            local native = (engine._api.FighterController._player_to_fighter or {})[player]
            local environment = read(native, "EnvironmentID") or (native and read(native.Entity, "EnvironmentID"))
                or player:GetAttribute("EnvironmentID")
            if not native or environment ~= engine._environment then continue end
            local team = player:GetAttribute("TeamID")
            if ownTeam ~= nil and team ~= nil and team == ownTeam then continue end
            if ownTeam == nil and team == nil and localPlayer.Team ~= nil and localPlayer.Team == player.Team then continue end
            local model = player.Character
            local humanoid = model and model:FindFirstChildOfClass("Humanoid")
            local root = model and model:FindFirstChild("HumanoidRootPart")
            local item = native.EquippedItem
            local info = item and item.Info
            if not humanoid or humanoid.Health <= 0 or not root or not info then continue end
            local distance = (root.Position - target.Root.Position).Magnitude
            local bladeMode = item.Name == "Gunblade" and read(item, "Mode") == "Blade"
            if (info.Type == "Melee" or bladeMode) and distance <= 75 and #self.Blades < 24 then
                local reach = math.max(number(info.AttackReach, 6, 0, 30),
                    number(info.HeavyAttackReach, 0, 0, 30), number(info.SpinRadius, 0, 0, 30),
                    bladeMode and number(info.BladeReach, 0, 0, 30) or 0)
                local dash = number(info.DashSpeed, 0, 0, 200) * number(info.DashDuration, 0, 0, 2)
                local closing = math.min(root.AssemblyLinearVelocity.Magnitude, 150)
                    * engine:_replicationWindow(localPlayer)
                self.Blades[#self.Blades + 1] = { Position = root.Position,
                    Radius = math.clamp(reach + dash + closing + 2, 3, 30), Model = model }
            elseif info.Type == "Gun" and model ~= target.Model and distance <= 250 then
                local head = model:FindFirstChild("HitboxHead") or model:FindFirstChild("Head")
                if head then candidates[#candidates + 1] = { Position = head.Position, Distance = distance } end
            end
        end
        table.sort(candidates, function(a, b) return a.Distance < b.Distance end)
        for index = 1, math.min(3, #candidates) do self.Watchers[index] = candidates[index].Position end
    end

    function Planner:_spreadDistance(part, info)
        local size = part.Size
        local half = math.max(0.05, math.min(size.X, size.Y, size.Z) * 0.45)
        local spread = number(info.ShootSpread, 0, 0, 85)
        if spread <= 0.01 then return 24 end
        return math.clamp(half / math.tan(math.rad(spread)), 3.5, 24)
    end

    function Planner:_score(point, target, part, ideal, below, now)
        if not vector(point) then return nil end
        local origin = point + Vector3.new(0, 3, 0)
        local distance = (origin - part.Position).Magnitude
        local scale = math.max(math.abs(part.Position.X), math.abs(part.Position.Y), math.abs(part.Position.Z))
        local maximum = math.max(64, scale / 1048576 * 4)
        if distance < 1.5 or distance > maximum then return nil end
        local unsafe = self.Unsafe[target.Model]
        if unsafe and now < unsafe.Until and (point - target.Root.Position - unsafe.Offset).Magnitude < 3 then return nil end
        local score = math.abs(distance - ideal)
        if distance > ideal then score += (distance - ideal) * 2 end
        local last = self.Last[target.Model]
        if last then score += (point - target.Root.Position - last).Magnitude * 0.15 end
        for _, blade in ipairs(self.Blades) do
            local clearance = (point - blade.Position).Magnitude
            score += math.max(0, blade.Radius - clearance) * 4
        end
        if below ~= nil and ((origin.Y < part.Position.Y) ~= below) then score += 20 end
        return score
    end

    function Planner:_exposure(point)
        local world = self.Engine._visibility and self.Engine._visibility._worldInclude
        local params = world and world:GetMapParams()
        if not params then return 0 end
        local exposed = 0
        local eye = point + Vector3.new(0, 3, 0)
        for _, from in ipairs(self.Watchers) do
            local delta = eye - from
            if delta.Magnitude > 0.01 then
                self.Stats.ExposureRays += 1
                if workspace:Raycast(from, delta, params) == nil then exposed += 1 end
            end
        end
        return exposed
    end

    function Planner:Choose(points, target, part, cfg)
        local now = self.Engine._clock()
        self:_threats(target, now)
        local item = self.Engine._api.FighterController.LocalFighter.EquippedItem
        local library = self.Engine._api.ItemLibrary
        local original = library and library.Items and item and library.Items[item.Name]
        local info = type(original) == "table" and original or (item and item.Info or {})
        local ideal = self:_spreadDistance(part, info)
        if number(info.ShootPellets, 1, 1, 100) > 1 then ideal = math.min(ideal, 7) end
        local below = self.Engine._tactics:ShieldBelow(target, cfg)
        local previous = self.Last[target.Model]
        if previous then table.insert(points, 1, target.Root.Position + previous) end
        
        
        for _, blade in ipairs(self.Blades) do
            if blade.Model == target.Model then
                local radius = math.clamp(blade.Radius + 1, 4, 24)
                for index = 0, 7 do
                    local angle = math.pi * index / 4
                    points[#points + 1] = part.Position + Vector3.new(math.cos(angle) * radius, -3, math.sin(angle) * radius)
                end
                break
            end
        end
        local ranked = {}
        for index, point in ipairs(points) do
            if index > 24 then break end
            local score = self:_score(point, target, part, ideal, below, now)
            if score then ranked[#ranked + 1] = { Point = point, Score = score, Index = index } end
        end
        table.sort(ranked, function(a, b)
            if a.Score == b.Score then return a.Index < b.Index end
            return a.Score < b.Score
        end)
        local finalists = {}
        for _, candidate in ipairs(ranked) do
            self.Stats.CandidateChecks += 1
            if self.Engine:_clear(candidate.Point + Vector3.new(0, 3, 0), part) then
                finalists[#finalists + 1] = candidate
                if #finalists == 3 then break end
            end
        end
        if #finalists == 0 then
            for index = 1, math.min(3, #ranked) do
                local candidate = ranked[index]
                if self.Engine._features:ManipulateOrigin(candidate.Point + Vector3.new(0, 3, 0),
                    part, cfg, self.Engine._visibility) then finalists[#finalists + 1] = candidate end
            end
        end
        local best, bestScore
        for _, candidate in ipairs(finalists) do
            local score = candidate.Score + self:_exposure(candidate.Point) * 6
            if not best or score < bestScore then best, bestScore = candidate.Point, score end
        end
        self.Stats.Plans += 1
        if best then self.Last[target.Model] = best - target.Root.Position end
        return best
    end

    function Planner:Prepare(record, target, part, cfg)
        record.TrackTarget = (cfg.Engine or {}).FollowTarget ~= false
            and (cfg.Engine or {}).Positioning ~= "Underground"
        record.Anchor = part.Position
        record.ObservedRoot = target.Root.Position
        record.InitialRoot = target.Root.Position
    end

    function Planner:WeaponBusy(item)
        local now = tick()
        local melee = item.Info and item.Info.Type == "Melee"
        local fields = melee and meleeCooldowns or gunCooldowns
        for _, field in ipairs(fields) do
            local deadline = tonumber(item[field])
            if deadline and deadline > now then return true end
        end
        return false
    end

    function Planner:Follow(record, target, part)
        if not target.Model.Parent or not target.Root.Parent or not part.Parent or target.Humanoid.Health <= 0 then return false end
        local point, root = part.Position, target.Root.Position
        if not vector(point) or not vector(root) then return false end
        local previous = record.TrackTarget and (record.ObservedRoot or root) or (record.InitialRoot or root)
        if (root - previous).Magnitude > 20 then
            self.Stats.TargetResets += 1
            return false
        end
        if record.TrackTarget then
            local shifted = record.Pose.Position + (point - (record.Anchor or point))
            if not vector(shifted) then return false end
            record.Pose = CFrame.new(shifted) * record.Pose.Rotation
        end
        record.Anchor, record.ObservedRoot = point, root
        return true
    end

    function Planner:DamageRetreat(cfg, state, now)
        local humanoid = state.Model and state.Model:FindFirstChildOfClass("Humanoid")
        local health = humanoid and humanoid.Health
        if self.Humanoid ~= humanoid then
            self.Humanoid, self.Health, self.RetreatUntil = humanoid, health, nil
            return false
        end
        local lost = health and self.Health and self.Health - health or 0
        self.Health = health
        if not ((cfg.Safety or {}).RetreatOnDamage == true) then self.RetreatUntil = nil; return false end
        local engine = self.Engine
        local native = engine._nativeRage
        local daggers = engine._daggers
        local attack = engine._attack or (native and native.Visit) or (daggers and daggers.Visit)
        local contact = engine._transport:HasOneFrame()
        if lost >= 6 and (attack or contact or (native and native.Job)) then
            local target = (attack and attack.Target) or engine._target
            local pose = (attack and attack.Pose) or engine._transport._pose
            if target and target.Model.Parent and pose then
                self.Unsafe[target.Model] = { Offset = pose.Position - target.Root.Position, Until = now + 1 }
            end
            self.RetreatUntil = now + 0.8
            self.Stats.DamageRetreats += 1
        end
        return now < (self.RetreatUntil or 0)
    end

    function Planner:Reset()
        table.clear(self.Last)
        table.clear(self.Unsafe)
        self.ThreatAt, self.ThreatTarget, self.Humanoid, self.Health, self.RetreatUntil = nil, nil, nil, nil, nil
        self.Blades, self.Watchers = nil, nil
    end
    return Planner
end)()

