local function fn35()


local NativeFire=tbl17.k9()
local FrameTransport=tbl17.kA()
local Features=tbl17.k5()
local Engine={}
Engine.__index=Engine

local function value(n,default,lo,hi)
    n=tonumber(n)
    if n==nil or n~=n or math.abs(n)==math.huge then n=default end
    return math.clamp(n,lo,hi)
end
local function read(object,key)
    if not object then return nil end
    local ok,result=pcall(function() return object:Get(key) end)
    if ok and result~=nil then return result end
    return object.Data and object.Data[key]
end
local function env(native,player)
    return read(native,"EnvironmentID") or read(native and native.Entity,"EnvironmentID") or (player and player:GetAttribute("EnvironmentID"))
end
local function alive(model)
    local humanoid=model and model:FindFirstChildOfClass("Humanoid")
    return humanoid and humanoid.Health>0 and humanoid
end

function Engine.new(fighters,tags,context,stateHook,_oldGlue,visibility,deps,boundary)
    deps=deps or {}
    local services=deps.Services or {
        Players=cloneref(game:GetService("Players")),
        RunService=cloneref(game:GetService("RunService")),
        HttpService=cloneref(game:GetService("HttpService")),
    }
    local api=deps.API or tbl17.aS()
    local random=deps.Random or Random.new()
    local clock=deps.Clock or os.clock
    local self=setmetatable({
        _api=api,_services=services,_context=context,_stateHook=stateHook,_boundary=deps.Boundary or boundary,
        _store=deps.Store or tbl17.bG(),_visibility=visibility,_tags=tags,
        _clock=clock,_random=random,_features=Features.new(random,clock),
        _sender=NativeFire.new(api,random),_parts=setmetatable({},{__mode="k"}),_connections={},_nextShot=setmetatable({},{__mode="k"}),
        _reloadAt=setmetatable({},{__mode="k"}),_reloadPending=setmetatable({},{__mode="k"}),
        _phase="idle",_enabled=false,_nextEquip=0,_nextReload=0,
        _stats={Requests=0,Bursts=0,ReloadRequests=0,Errors=0,Updates=0,TotalSeconds=0,MaxSeconds=0,Status="Idle"},
    },Engine)
    self._transport=deps.Transport or FrameTransport.new(services.RunService,"Absense.Rage."..services.HttpService:GenerateGUID(false))
    self._tactics=absenseRageTactics.new(self,deps)
    self._planner=absenseRagePlanner.new(self)
    self._connections[1]=services.RunService.PreSimulation:Connect(function()
        if not self._enabled and self._features._model==nil then return end
        local inner=self._context.Inner
        local state=inner and inner.FighterState.Character.State
        self._features:ApplyJoints(self._enabled and state and state.Alive and state.Model or nil,self._store.Data.Ragebot)
    end)
    self._connections[2]=context.ContextRemoved:Connect(function() self:_stop("Waiting for character") end)
    return self
end

function Engine:_settings()
    local raw=self._store.Data.Ragebot
    local engine,silent=raw.Engine or {},raw.SilentAim or {}
    local manipulation=silent.Manipulation or {}
    if self._settingsSource~=raw then
        self._settingsSource=raw
        self._effectiveSettings=setmetatable({},{__index=raw})
    end
    if self._engineSource~=engine then
        self._engineSource=engine
        self._effectiveEngine=setmetatable({EyeHeight=3,MuzzleUp=.4},{__index=engine})
    end
    if self._silentSource~=silent then
        self._silentSource=silent
        self._effectiveSilent=setmetatable({Enabled=true,HitChance=100},{__index=silent})
    end
    if self._manipulationSource~=manipulation then
        self._manipulationSource=manipulation
        self._effectiveManipulation=setmetatable({Enabled=true},{__index=manipulation})
    end
    self._effectiveSettings.Engine=self._effectiveEngine
    self._effectiveSilent.Manipulation=self._effectiveManipulation
    self._effectiveSettings.SilentAim=self._effectiveSilent
    return self._effectiveSettings
end

function Engine:_isEnabled(cfg)
    local bind=cfg.Keybind
    return cfg.Enabled==true and (bind==nil or bind.Bind==nil or bind.State==true)
end

function Engine:_partsFor(player)
    local model=player.Character
    local health=alive(model)
    if not health then self._parts[player]=nil; return nil end
    local p=self._parts[player]
    if not p or p.Model~=model or not p.Root.Parent or not p.Head.Parent then
        local root=model:FindFirstChild("HumanoidRootPart")
        local head=model:FindFirstChild("HitboxHead") or model:FindFirstChild("Head")
        if not root or not head then return nil end
        p={Player=player,Model=model,Root=root,Head=head,Body=model:FindFirstChild("HitboxBody") or root,Humanoid=health}
        self._parts[player]=p
    end
    if not NativeFire.valid(p.Root.Position) or not NativeFire.valid(p.Head.Position) then return nil end
    return p
end

function Engine:_eligible(player,localNative,localEnv)
    local lp=self._services.Players.LocalPlayer
    if player==lp or player.Parent==nil then return nil end
    local native=(self._api.FighterController._player_to_fighter or {})[player]
    if not native or env(native,player)~=localEnv then return nil end
    local ownTeam,otherTeam=lp:GetAttribute("TeamID"),player:GetAttribute("TeamID")
    if ownTeam~=nil and otherTeam~=nil and ownTeam==otherTeam then return nil end
    if ownTeam==nil and otherTeam==nil and lp.Team~=nil and lp.Team==player.Team then return nil end
    local p=self:_partsFor(player)
    if not p then return nil end
    p.Native=native
    local cfg=self:_settings()
    if not self._tactics:Eligible(p,native,localNative.EquippedItem,cfg) then return nil end
    return p
end

function Engine:_targetRank(target,cfg,origin)
    local targeting=cfg.Targeting or {}
    local listed=targeting.PriorityPlayers and (targeting.PriorityPlayers[target.Player.Name]==true or targeting.PriorityPlayers[tostring(target.Player.UserId)]==true)
    local hacker=cfg.PrioritizeHackers and self._tags and self._tags:Has(target.Player,"Hacker")
    local tier=listed and 0 or hacker and 1 or 2
    local distance=(target.Root.Position-origin).Magnitude
    local metric=target.Humanoid.Health
    local voidTier=0
    if targeting.Priority=="Closest" then metric=distance
    elseif targeting.Priority=="VoidedFirst" then
        local limit=value(targeting.VoidDistance,1000000,10000,10000000)
        local voided=target.Root.Position.Magnitude>limit or target.Root.Position.Y<(self._originalFloor or -500)
        voidTier=voided and 0 or 1
    end
    return {tier,voidTier,metric,distance}
end

function Engine:_selectTarget(localNative,localEnv,cfg,origin)
    origin=origin or Vector3.zero
    local targeting=cfg.Targeting or {}
    local signature=tostring(targeting.Priority)..":"..tostring(targeting.PriorityPlayers)..":"..tostring(targeting.VoidDistance)..":"..tostring(cfg.PrioritizeHackers)
    local current=self._targetPlayer and self:_eligible(self._targetPlayer,localNative,localEnv)
    if current and signature==self._targetSignature and self._clock()<(self._targetScanAt or 0) then return current end
    self._targetSignature=signature;self._targetScanAt=self._clock()+.1
    local best,bestRank=current,current and self:_targetRank(current,cfg,origin)
    local function better(rank,other)
        for index=1,4 do
            if rank[index]~=other[index] then return rank[index]<other[index] end
        end
        return false
    end
    for _,player in ipairs(self._services.Players:GetPlayers()) do
        local candidate=self:_eligible(player,localNative,localEnv)
        if candidate then
            local rank=self:_targetRank(candidate,cfg,origin)
            if not best or better(rank,bestRank) then best,bestRank=candidate,rank end
        end
    end
    self._targetPlayer=best and best.Player
    return best
end


function Engine:_ammoState(item)
    if item.Info.Type=="Melee" then return "Ready" end
    local capacity=tonumber(item.Info.MaxAmmo)
    if capacity and (capacity<=0 or capacity==math.huge) then return "Ready" end
    local ammo,reserve=read(item,"Ammo"),read(item,"AmmoReserve")
    if type(ammo)=="number" and ammo>0 then return "Ready" end
    if type(reserve)=="number" and reserve>0 then return "Reload" end
    
    
    if type(ammo)=="number" and ammo>=0 and reserve==nil then return "Reload" end
    return "Exhausted"
end

function Engine:_reloadBusy(item)
    if self._reloadPending[item] or (tonumber(item._reload_cooldown) or 0)>tick() then return true end
    if item.Info.ReloadType=="Segmented" then
        local threads=item._reload_threads or {}
        local thread=threads[#threads]
        
        
        if type(thread)=="thread" then
            local ok,status=pcall(coroutine.status,thread)
            if ok and status~="dead" then return true end
        end
    end
    return false
end

function Engine:_weapon(native,cfg)
    local settings=cfg.Weapons or {}
    if settings.Selection~="Priority" then
        local item=native.EquippedItem
        if not absenseRageTactics.IsCombatItem(item) then return nil,nil,false,"Equip a combat weapon" end
        local state=self:_ammoState(item)
        if state=="Exhausted" then return nil,nil,false,"Equipped weapon has no ammunition" end
        return item,tonumber(read(item,"ItemIndex")),state=="Reload"
    end
    local enabled=settings.Enabled or {Primary=true,Secondary=true,Melee=true}
    local priority=settings.Priority or {"Primary","Secondary","Melee"}
    local best,slot,bestRank,reload,reloadSlot,reloadRank,any
    for key,item in pairs(native.Items or {}) do
        local index=tonumber(read(item,"ItemIndex")) or tonumber(key)
        local category=index==1 and "Primary" or index==2 and "Secondary" or index==3 and "Melee" or nil
        local kind=item.Info and item.Info.Type
        if category and enabled[category]~=false and absenseRageTactics.IsCombatItem(item) then
            any=true
            local rank=table.find(priority,category) or 99
            if settings.PreferProjectiles and kind=="Gun" and item.Info.IsRaycast==false then rank-=100 end
            local state=self:_ammoState(item)
            if state=="Ready" then
                if not best or rank<bestRank then best,slot,bestRank=item,index,rank end
            elseif state=="Reload" then
                if not reload or rank<reloadRank then reload,reloadSlot,reloadRank=item,index,rank end
            end
        end
    end
    local policy=settings.OnEmpty or "SwapOrReload"
    if reload and policy=="Reload" and (not best or reloadRank<bestRank) then return reload,reloadSlot,true end
    if best then return best,slot,false end
    if policy~="Swap" and reload then return reload,reloadSlot,true end
    return nil,nil,false,any and "No ammunition" or "No enabled weapon"
end

function Engine:_requestReload(native,item)
    local now=self._clock()
    if self:_reloadBusy(item) or now<(self._reloadAt[item] or 0) then return end
    self._reloadAt[item]=now+.5;self._reloadPending[item]=true
    local context=self._context.Inner
    task.spawn(function()
        local function current()
            return not self._destroyed and self._enabled and self._context.Inner==context
                and self._api.FighterController.LocalFighter==native and native.EquippedItem==item
        end
        local ok,requested,reason=pcall(function()
            if not current() then return false,"reload cancelled" end
            return self._sender:Reload(item,current)
        end)
        self._reloadPending[item]=nil
        if ok and requested then self._stats.ReloadRequests+=1;self._stats.LastReloadError=nil
        elseif not ok then self._stats.Errors+=1;self._stats.LastReloadError=tostring(requested)
        elseif reason~="reload cancelled" then self._stats.LastReloadError=reason end
    end)
end

function Engine:_equip(native,slot)
    local now=self._clock()
    if now<self._nextEquip then return end
    self._nextEquip=now+0.25
    local context=self._context.Inner
    
    task.spawn(function()
        if self._destroyed or not self._enabled or self._context.Inner~=context or self._api.FighterController.LocalFighter~=native then return end
        local ok,err=pcall(function() native:EquipItem(slot) end)
        if not ok then self._stats.LastError=tostring(err) end
    end)
end

function Engine:_clear(origin,part)
    local world=self._visibility and self._visibility._worldInclude
    local params=world and world:GetMapParams()
    if self._visibility and self._visibility.Check then
        return self._visibility:Check(origin,part,part.Parent,{Point=part.Position,Surface=false})==true
    end
    if params==nil then return false end
    return workspace:Raycast(origin,part.Position-origin,params)==nil
end

function Engine:_asTarget(target)
    return {AliveState={RootPart=target.Root,HitboxHead=target.Head,HitboxBody=target.Body,Alive=true},FighterState=target.Native}
end

function Engine:_part(target,cfg)
    local silent=cfg.SilentAim
    if not silent or not silent.Enabled then return target.Head end
    if silent.TargetPart=="Body" then return target.Body end
    if silent.TargetPart=="Root" then return target.Root end
    if silent.TargetPart=="Random" then return self._random:NextNumber()<0.5 and target.Head or target.Body end
    return target.Head
end

function Engine:_position(target,part,ownRoot,cfg,melee)
    local settings=cfg.Engine or {}
    local previous=self._blockedPosition
    if previous and previous.Target==target.Model and previous.Mode==settings.Positioning
        and self._clock()<previous.Until and (previous.Point-part.Position).Magnitude<1 then return nil end
    local strategyPose,handled=self._tactics:Position(target,part,ownRoot,cfg,melee)
    if handled then return strategyPose end
    local eye=value(settings.EyeHeight,3,0.5,8)
    local root=target.Root
    local scale=math.max(math.abs(root.Position.X),math.abs(root.Position.Y),math.abs(root.Position.Z))
    local gap=math.max(melee and 2.2 or 4,scale/1048576)
    local points
    if melee then
        points={root.Position-root.CFrame.LookVector*gap+Vector3.new(0,0.5,0),root.Position+root.CFrame.RightVector*gap}
    else
        local orbit=self._features:OrbitPose(self:_asTarget(target),ownRoot,cfg)
        points={}
        if orbit then points[#points+1]=orbit.Position end
        
        local below=self._tactics:ShieldBelow(target,cfg)
        if below~=nil then
            table.insert(points,1,part.Position+Vector3.new(0,(below and -1 or 1)*math.max(6,scale/1048576)-eye,0))
        end
        points[#points+1]=part.Position+Vector3.new(0,math.max(2.5,scale/1048576),0)
        points[#points+1]=root.Position-root.CFrame.LookVector*gap+Vector3.new(0,0.5,0)
        points[#points+1]=root.Position+root.CFrame.RightVector*gap+Vector3.new(0,0.5,0)
        points[#points+1]=root.Position-root.CFrame.RightVector*gap+Vector3.new(0,0.5,0)
    end
    if not melee then
        
        for index=0,7 do
            local angle=math.pi*2*index/8
            points[#points+1]=part.Position+Vector3.new(math.cos(angle)*9,-eye,math.sin(angle)*9)
        end
    end
    if not melee and (cfg.Safety or {}).SaferPositions~=false and not (cfg.AntiAim and cfg.AntiAim.Enabled) then
        local point=self._planner:Choose(points,target,part,cfg)
        if point then return self._tactics:Orient(self._features:OrientPose(CFrame.new(point),cfg),target,cfg) end
        self._blockedPosition={Target=target.Model,Point=part.Position,Mode=settings.Positioning,Until=self._clock()+0.1}
        return nil
    end
    for _,point in ipairs(points) do
        if NativeFire.valid(point) and self:_clear(point+Vector3.new(0,eye,0),part) then
            return self._tactics:Orient(self._features:OrientPose(CFrame.new(point),cfg),target,cfg)
        end
    end
    if cfg.SilentAim and cfg.SilentAim.Manipulation and cfg.SilentAim.Manipulation.Enabled then
        for index=1,math.min(#points,3) do
            local point=points[index]
            if self._features:ManipulateOrigin(point+Vector3.new(0,eye,0),part,cfg,self._visibility) then
                return self._tactics:Orient(self._features:OrientPose(CFrame.new(point),cfg),target,cfg)
            end
        end
    end
    self._blockedPosition={Target=target.Model,Point=part.Position,Mode=settings.Positioning,Until=self._clock()+0.1}
    return nil
end

function Engine:_idle(home,target,ownRoot,cfg)
    local pose=self._tactics:IdlePose(home,ownRoot,cfg,self._pauseReason~=nil)
        or self._features:IdlePose(target and self:_asTarget(target),ownRoot,cfg)
    if not pose and cfg.Evasion and cfg.Evasion.Mode~="Off" then
        self._fallbackConfig=self._fallbackConfig or {VoidSpam={Enabled=true,IntervalMS=33,MinDistance=100000}}
        self._fallbackConfig.AntiAim=cfg.AntiAim
        pose=self._features:VoidPose(self._fallbackConfig)
    end
    self._transport:Park(pose or home)
    self._evadingInVoid=pose~=nil and (pose.Position-home.Position).Magnitude>=1000
    local angles=self._features:ViewAngles(cfg)
    if self._innerContext then self._innerContext.CharacterController:SendViewAngles(20,angles) end
end

function Engine:_cancelPhase()
    if self._attack and self._attack.FiredAt then
        self._stats.LastExposureMS=(self._clock()-self._attack.StartedAt)*1000
    end
    self._phase="idle"
    self._attack=nil
end

function Engine:_replicationWindow(player)
    
    local ping=0
    local ok,result=pcall(function() return player:GetNetworkPing() end)
    if ok then ping=value(result,0,0,1) end
    return math.clamp(ping*2+2/60,0.1,0.25)
end

function Engine:_tick(dt)
    local cfg=self:_settings()
    local desired=self:_isEnabled(cfg)
    self._enabled=desired
    local anti=cfg.Safety and cfg.Safety.AntiOutOfBounds==true
    if self._boundary then self._boundary:SetClientCheckDisabled(anti) end
    local inner=self._context.Inner
    self._innerContext=inner
    if not desired then self:_stop("Disabled"); return end
    local lp=self._services.Players.LocalPlayer
    local native=self._api.FighterController.LocalFighter
    local state=inner and inner.FighterState.Character.State
    local environment=env(native,lp)
    if not inner or not native or not state or not state.Alive or environment==nil then self:_stop("Waiting for match"); return end
    if not state.RootPart or not state.RootPart.Parent then self:_stop("Waiting for character"); return end
    
    
    if next(native.Items or {})==nil then self:_stop("Waiting for loadout"); return end
    self:_setVoidProtection(true)
    self._transport:Bind(inner.CharacterController,state.RootPart)
    local home=self._transport:BeginFrame()
    if home==nil then self:_stop("Waiting for character"); return end
    local now=self._clock()
    self._environment=environment
    if self._tactics:TrackWeapon(native.EquippedItem,now) then
        if self._daggers then self._daggers:Reset() end
        if self._nativeRage then self._nativeRage:Reset() end
        self:_cancelPhase()
    end
    local hurt=self._planner:DamageRetreat(cfg,state,now)
    local pause=self._tactics:Update(cfg,native,environment,home,now)
    if hurt then pause="Retreating after damage" end
    if pause then
        if self._pauseReason~=pause then
            if self._daggers then self._daggers:Reset() end
            if self._nativeRage then self._nativeRage:Reset() end
            self:_cancelPhase()
        end
        self._pauseReason=pause
        self._stats.Status=pause
        self:_idle(home,self._target,state.RootPart,cfg)
        return
    end
    self._pauseReason=nil
    if now<(self._tactics.EquipUntil or 0) then
        self._stats.Status="Settling equipped weapon"
        self:_idle(home,self._target,state.RootPart,cfg)
        return
    end
    local firingMode=(cfg.Engine or {}).Mode or "Standard"
    if self._firingMode~=firingMode then
        if self._daggers then self._daggers:Reset() end
        if self._nativeRage then self._nativeRage:Reset() end
        self:_cancelPhase()
        self._firingMode=firingMode
    end
    local equipped=inner.ItemBehaviors and inner.ItemBehaviors:GetEquipped()
    if firingMode=="Standard" and equipped and equipped.Name=="Gunblade" then firingMode="Gunblade" end
    if firingMode=="Gunblade" or firingMode=="Knife" then
        self._nativeRage=self._nativeRage or absenseNativeRage.new(self)
        self._nativeRage:Tick(dt,cfg,native,lp,state,environment,home,firingMode)
        return
    end
    if firingMode=="Daggers" then
        self._daggers=self._daggers or absenseDaggersMode.new(self)
        self._daggers:Tick(dt,cfg,native,lp,state,environment,home)
        return
    end
    
    
    if self._phase=="hold" then
        local shot=self._attack
        if not shot or not self._planner:Follow(shot,shot.Target,shot.Part) then
            self:_cancelPhase();self._stats.Status="Target lost; returning to cover"
            self:_idle(home,nil,state.RootPart,cfg);return
        end
        if now<self._holdUntil or (shot.Protected and self._transport:GetSimulationSteps()<self._holdSteps) then
            self._transport:Park(shot.Pose,shot.Protected)
            self._stats.Status="Completing shot"
            return
        end
        self:_cancelPhase()
        self._stats.Status="Returning to cover"
        self:_idle(home,self._target,state.RootPart,cfg)
        return
    end
    
    
    local target=self._attack and self:_eligible(self._attack.Target.Player,native,environment)
    if not target then target=self:_selectTarget(native,environment,cfg,home.Position) end
    self._target=target
    self._lastTargetWorld=target and target.Root.Position
    local item,slot,needsReload,weaponStatus=self:_weapon(native,cfg)
    self._item=item
    if now<(self._retryAt or 0) then self._stats.Status="Recovering"; self:_idle(home,target,state.RootPart,cfg); return end
    if not item then self:_cancelPhase(); self._stats.Status=weaponStatus or "No enabled weapon"; self:_idle(home,target,state.RootPart,cfg); return end
    if native.EquippedItem~=item then
        self:_cancelPhase(); self:_equip(native,slot); self._stats.Status="Equipping"; self:_idle(home,target,state.RootPart,cfg); return
    end
    if needsReload or self:_reloadBusy(item) then
        self:_cancelPhase()
        if needsReload then self:_requestReload(native,item) end
        self._stats.Status=self._stats.LastReloadError or "Reloading";self:_idle(home,target,state.RootPart,cfg);return
    end
    if not target then self:_cancelPhase(); self._stats.Status="No eligible target"; self:_idle(home,nil,state.RootPart,cfg); return end
    if self._attack and (self._attack.Target~=target or self._attack.Item~=item or not self._attack.Part.Parent) then self:_cancelPhase() end
    local settings=cfg.Engine or {}
    if self._phase=="idle" then
        if self._tactics:Waiting(item) then
            self._stats.Status="Waiting for hit confirmation"
            self:_idle(home,target,state.RootPart,cfg)
            return
        end
        if now<(self._nextShot[item] or 0) or self._planner:WeaponBusy(item) then self._stats.Status="Weapon cooldown"; self:_idle(home,target,state.RootPart,cfg); return end
        local part=self:_part(target,cfg)
        local melee=item.Info.Type=="Melee"
        local pose=self:_position(target,part,state.RootPart,cfg,melee)
        if not pose then self._stats.Status="No clear firing position"; self:_idle(home,target,state.RootPart,cfg); return end
        local minimum=settings.Timing~="Custom"
        local networkRequired=(cfg.VoidSpam and cfg.VoidSpam.Enabled==true) or self._evadingInVoid==true
            or (cfg.Evasion and cfg.Evasion.Mode~="Off") or (minimum and (pose.Position-home.Position).Magnitude>8)
        local protected=minimum or networkRequired
        local window=networkRequired and self:_replicationWindow(lp) or 0
        local steps=networkRequired and 2 or (minimum and 1 or 2)
        local settle=math.max(minimum and 0 or value(settings.SettleMS,33,0,250)/1000,window)
        self._attack={Target=target,Part=part,Item=item,Pose=pose,RootPosition=target.Root.Position,Melee=melee,
            Protected=protected,Window=window,Minimum=minimum,Steps=steps,StartedAt=now,NetworkRequired=networkRequired}
        self._planner:Prepare(self._attack,target,part,cfg)
        self._phase="settle"
        self._readyAt=now+settle
        self._readySteps=self._transport:GetSimulationSteps()+steps
    end
    local shot=self._attack
    if not self._planner:Follow(shot,target,shot.Part) then
        self:_cancelPhase(); self._stats.Status="Target teleported; repositioning"
        self:_idle(home,target,state.RootPart,cfg); return
    end
    self._transport:Park(shot.Pose,shot.Protected)
    if now<self._readyAt or (shot.Protected and self._transport:GetSimulationSteps()<self._readySteps) then
        self._stats.Status=shot.NetworkRequired and "Synchronizing position" or "Positioning"; return
    end
    local origin=shot.Pose.Position+Vector3.new(0,value(settings.EyeHeight,3,0.5,8),0)
    origin=self._features:ManipulateOrigin(origin,shot.Part,cfg,self._visibility)
    if origin==nil then self:_cancelPhase(); self._stats.Status="Origin blocked"; self:_idle(home,target,state.RootPart,cfg); return end
    if not self._features:ShouldRedirect(cfg) then self:_cancelPhase(); self._nextShot[item]=now+0.05; self:_idle(home,target,state.RootPart,cfg); return end
    if not self:_eligible(target.Player,native,environment) then
        self:_cancelPhase();self._stats.Status="Target became protected"
        self:_idle(home,nil,state.RootPart,cfg);return
    end
    if self._planner:WeaponBusy(item) then
        self:_cancelPhase();self._stats.Status="Weapon busy; returning to cover"
        self:_idle(home,target,state.RootPart,cfg);return
    end
    local beforeAmmo=read(item,"Ammo")
    local sent,reason=Features.WithShot(function()
        return self._sender:Send(item,shot.Part,origin,target.Root.AssemblyLinearVelocity,settings,shot.Melee)
    end)
    self._stats.Requests+=sent
    if sent>0 then
        self._tactics:RecordShot(item,target,beforeAmmo)
        self._stats.Bursts+=1
        self._stats.LastShot={Time=now,Target=target.Player.Name,Health=target.Humanoid.Health,Ammo=beforeAmmo,
            Stationary=target.Root.AssemblyLinearVelocity.Magnitude<0.5,Requests=sent}
        local cooldown=self._sender:Cooldown(item,shot.Melee)
        self._nextShot[item]=now+cooldown
        self._phase="hold"
        shot.FiredAt=now
        self._holdUntil=now+math.max(shot.Minimum and 0 or value(settings.HoldMS,17,0,250)/1000,shot.Window)
        self._holdSteps=self._transport:GetSimulationSteps()+shot.Steps
        self._stats.Status="Fired"
    else
        self:_cancelPhase(); self._stats.Status=reason or "No packet sent"; self._retryAt=now+0.1
        self:_idle(home,target,state.RootPart,cfg)
    end
end

function Engine:Update(dt)
    if self._destroyed or self._updating then return end
    local raw=self._store.Data.Ragebot
    if not self:_isEnabled(raw) then
        local safety=raw.Safety and raw.Safety.AntiOutOfBounds==true
        local inner=self._context.Inner
        if not self._idleStopped or self._idleSafety~=safety or self._idleContext~=inner then
            self._enabled=false;self._innerContext=inner
            self:_stop("Disabled")
            self._idleStopped=true;self._idleSafety=safety;self._idleContext=inner
        end
        return
    end
    self._idleStopped=false
    self._updating=true
    local start=self._clock()
    local ok,err=pcall(self._tick,self,dt)
    self._updating=false
    local cost=self._clock()-start
    local stats=self._stats
    stats.Updates+=1; stats.TotalSeconds+=cost; stats.MaxSeconds=math.max(stats.MaxSeconds,cost)
    if not ok then
        stats.Errors+=1; stats.LastError=tostring(err)
        self:_stop("Error: "..tostring(err))
        self._retryAt=self._clock()+0.25
        if self._clock()>=(self._warnAt or 0) then self._warnAt=self._clock()+2; warn("[Kicia Rage] "..tostring(err)) end
    end
end

function Engine:_stop(status)
    if self._daggers then self._daggers:Reset() end
    if self._nativeRage then self._nativeRage:Reset() end
    self:_cancelPhase()
    self._tactics:Reset()
    self._planner:Reset()
    self._pauseReason=nil
    self._blockedPosition=nil
    self._transport:Release()
    self._features:Reset()
    self._targetPlayer,self._target,self._lastTargetWorld=nil,nil,nil
    self._evadingInVoid=nil
    self._targetScanAt=nil;self._targetSignature=nil
    self._stats.Status=status
    local settings=self._store.Data.Ragebot
    local anti=(not self._destroyed and settings.Safety and settings.Safety.AntiOutOfBounds==true)==true
    self:_setVoidProtection(anti)
    if self._boundary then self._boundary:SetClientCheckDisabled(anti) end
    if self._innerContext then self._innerContext.CharacterController:SendViewAngles(20,nil) end
    if self._stateHook then self._stateHook:ClearForced("IsCrouching") end
end

function Engine:_setVoidProtection(enabled)
    if self._voidProtection==enabled then return end
    self._voidProtection=enabled
    if self._originalFloor==nil then
        local height=workspace.FallenPartsDestroyHeight
        self._originalFloor=type(height)=="number" and height==height and height or -500
    end
    local identity
    if type(getthreadidentity)=="function" then local ok,v=pcall(getthreadidentity); if ok then identity=v end end
    if identity and type(setthreadidentity)=="function" then pcall(setthreadidentity,8) end
    pcall(function()
        local height=enabled and (0/0) or self._originalFloor
        if type(sethiddenproperty)=="function" then sethiddenproperty(workspace,"FallenPartsDestroyHeight",height)
        else workspace.FallenPartsDestroyHeight=height end
    end)
    if identity and type(setthreadidentity)=="function" then pcall(setthreadidentity,identity) end
end

function Engine:SetEnabled(enabled)
    self._store:Set({"Ragebot","Enabled"},enabled==true)
    if not enabled then self._enabled=false; self:_stop("Disabled") end
end
function Engine:GetLastTargetWorld() return self._lastTargetWorld end
function Engine:GetDebugState()
    local out=table.clone(self._stats)
    out.Enabled=self._enabled; out.Phase=self._phase
    out.Weapon=self._item and self._item.Name
    out.Ammo=self._item and read(self._item,"Ammo")
    out.Reserve=self._item and read(self._item,"AmmoReserve")
    out.AmmoState=self._item and self:_ammoState(self._item)
    out.TargetPriority=(self:_settings().Targeting or {}).Priority or "LowestHealth"
    out.TargetHealth=self._target and self._target.Humanoid.Health
    out.Target=self._target and self._target.Player.Name
    out.VoidShotProtected=self._attack and self._attack.Protected or false
    out.ReplicationWindowMS=self._attack and self._attack.Window*1000 or 0
    out.PositionWaitMS=self._phase=="settle" and math.max(0,(self._readyAt or 0)-self._clock())*1000 or 0
    out.SimulationWaitSteps=self._phase=="settle" and math.max(0,(self._readySteps or 0)-self._transport:GetSimulationSteps()) or 0
    out.AttackTiming=(self:_settings().Engine or {}).Timing or "Minimum"
    out.FiringMode=(self:_settings().Engine or {}).Mode or "Standard"
    out.Daggers=self._daggers and table.clone(self._daggers.Stats) or nil
    out.NativeCombat=self._nativeRage and table.clone(self._nativeRage.Stats) or nil
    out.Tactics=table.clone(self._tactics.Stats)
    out.PositionPlanner=table.clone(self._planner.Stats)
    out.CoverStrategy=(self:_settings().Engine or {}).Positioning or "Adaptive"
    out.WeaponSelection=(self:_settings().Weapons or {}).Selection or "Equipped"
    out.HitConfirmationAvailable=self._tactics.HitBinding~=nil
    out.BoundaryProtection=self._boundary and self._boundary:GetDebugState() or nil
    out.AverageMS=out.Updates>0 and out.TotalSeconds/out.Updates*1000 or 0
    return out
end
function Engine:Destroy()
    if self._destroyed then return end
    self._destroyed=true; self._enabled=false
    self:_stop("Unloaded")
    self._tactics:Destroy()
    self._transport:Destroy()
    for _,connection in ipairs(self._connections) do connection:Disconnect() end
end
return Engine
end

