            if global then
                if mode.Curvature == nil then mode.Curvature = 0.35 end
                if mode.Randomness == nil then mode.Randomness = 0.15 end
                if mode.Smoothness == nil then mode.Smoothness = 0.5 end
                if mode.EdgeTracking == nil then mode.EdgeTracking = 0 end
            end
        end
    end
    local function timings(branch)
        if type(branch) ~= "table" then return end
        
        for _, key in ipairs({ "ReactionTime", "SwitchDelay" }) do
            if type(branch[key]) == "number" then branch[key] = math.clamp(branch[key], 0, 1) end
        end
    end
    local function profile(p, global)
        if type(p) ~= "table" then return end
        aim(p.Aimbot, global)
        timings(p.Aimbot)
        timings(p.SilentAim)
        timings(p.Triggerbot)
        for _,branch in ipairs({p.Aimbot or {},p.SilentAim or {}}) do
            branch.SwitchDelay=branch.ReactionTime
            if type(branch.HitboxSelection)=="table" then branch.HitboxSelection.Type="ClosestToCrosshair" end
        end
    end
    if type(data) ~= "table" then return data end
    if type(data.Ragebot) == "table" then
        local function merge(dst, defaults)
            for key, value in pairs(defaults) do
                if type(value) == "table" then
                    if type(dst[key]) ~= "table" then dst[key] = {} end
                    merge(dst[key], value)
                elseif dst[key] == nil then dst[key] = value end
            end
        end
        merge(data.Ragebot, tbl17.k7())
        if data.Ragebot.UtilizeHealthLead==true then
            data.Ragebot.Safety.HealthLead=true
            data.Ragebot.UtilizeHealthLead=false
        end
        data.Ragebot.SilentAim.Enabled=true
        data.Ragebot.SilentAim.HitChance=100
        data.Ragebot.SilentAim.Manipulation.Enabled=true
        data.Ragebot.Engine.EyeHeight=3
        data.Ragebot.Engine.MuzzleUp=0.4
        if data.Ragebot.Engine.Mode~="Knife" then data.Ragebot.Engine.Mode="Standard" end
        data.Ragebot.Keybind=data.Ragebot.Keybind or {}
        data.Ragebot.Keybind.Kind="Toggle"
        data.Ragebot.WildcatPullDown.Enabled=data.ItemModifiers and data.ItemModifiers.Recoil and data.ItemModifiers.Recoil.Enabled==true or false
        for _,name in ipairs({"WalkSpeed","Sliding","JumpPower"}) do
            local item=data.Movement and data.Movement[name]
            if item then item.Keybind={Kind="Always",State=true,ShowInList=false,Invisible=true} end
        end
        local spam = data.Ragebot.VoidSpam
        if type(spam.MinDistance) ~= "number" or spam.MinDistance ~= spam.MinDistance or spam.MinDistance > 1000000 then spam.MinDistance=100000 end
        spam.MinDistance=math.clamp(spam.MinDistance,10000,1000000)
    end
    if type(data.Esp)=="table" then data.Esp.Settings=tbl17.bg().Esp.Settings end
    profile(data, true)
    local overrides = data.PerProfile and data.PerProfile.Overrides
    if type(overrides) == "table" then
        for _, p in pairs(overrides) do profile(p, false) end
    end
    return data
end

return normalize
end

