local function fn35()
local positions = tbl17.k4()
local Runtime = {}
Runtime.__index = Runtime
local shotDepth = 0

local function number(value, fallback, lo, hi)
    value = tonumber(value)
    if value == nil or value ~= value or math.abs(value) == math.huge then value = fallback end
    return math.clamp(value, lo, hi)
end

function Runtime.new(random, clock)
    return setmetatable({ _random = random or Random.new(), _clock = clock or os.clock, _joints = {} }, Runtime)
end

function Runtime.IsRageShot() return shotDepth > 0 end
function Runtime.WithShot(fn)
    shotDepth += 1
    local result = table.pack(pcall(fn))
    shotDepth -= 1
    if not result[1] then error(result[2], 0) end
    return table.unpack(result, 2, result.n)
end

function Runtime:SelectGunPart(target, config)
    local state = target.AliveState
    local settings = config.SilentAim
    if settings == nil or not settings.Enabled then return state.HitboxHead end
    local choice = settings.TargetPart
    if choice == "Random" then choice = self._random:NextNumber() < 0.5 and "Head" or "Body" end
    if choice == "Body" then return state.HitboxBody or state.HitboxHead end
    if choice == "Root" then return state.RootPart end
    return state.HitboxHead
end

function Runtime:ShouldRedirect(config)
    local silent = config.SilentAim
    if silent == nil or not silent.Enabled then return true end
    local chance = number(silent.HitChance, 100, 0, 100)
    return chance >= 100 or self._random:NextNumber(0, 100) < chance
end

function Runtime:ManipulateOrigin(origin,part,config,visibility)
    local settings=config.SilentAim and config.SilentAim.Manipulation or {}
    if not visibility then return settings.RequireVisible and nil or origin end
    local _,point=searchShotOrigin(visibility,origin,part,settings.Radius,28)
    return point or (not settings.RequireVisible and origin or nil)
end

function Runtime:GetYaw(config)
    local aa = config.AntiAim
    if aa == nil or not aa.Enabled then return nil end
    local yaw = number(aa.Yaw, 0, -180, 180)
    if aa.YawMode == "Spin" then yaw += self._clock() * number(aa.SpinSpeed, 360, -720, 720)
    elseif aa.YawMode == "Random" then
        local now = self._clock()
        local interval = number(aa.RepositionMS, 100, 1, 1000) / 1000
        if self._yawAt == nil or now - self._yawAt >= interval then
            self._yawAt, self._randomYaw = now, self._random:NextNumber(-180, 180)
        end
        yaw += self._randomYaw
    end
    return (yaw + 180) % 360 - 180
end

function Runtime:OrientPose(pose, config)
    local yaw = self:GetYaw(config)
    if pose == nil or yaw == nil then return pose end
    local aa = config.AntiAim
    return CFrame.new(pose.Position) * CFrame.fromOrientation(
        math.rad(number(aa.BodyPitch, 0, -180, 180)), math.rad(yaw), math.rad(number(aa.BodyRoll, 0, -180, 180)))
end

function Runtime:ViewAngles(config)
    local yaw = self:GetYaw(config)
    if yaw == nil then return nil end
    local pitch = number(config.AntiAim.ViewPitch,0,-89,89)
    yaw = math.floor(yaw*4+0.5)/4
    if self._viewAngles and self._viewAngles.Pitch==pitch and self._viewAngles.Yaw==yaw then return self._viewAngles end
    self._viewAngles = { Kind="Normalized", Pitch=pitch, Yaw=yaw }
    return self._viewAngles
end

function Runtime:OrbitPose(target, ownRoot, config)
    local aa = config.AntiAim
    if aa == nil or not aa.Enabled or not positions.CanAttack(target) then return nil end
    local root = target.AliveState.RootPart
    local now = self._clock()
    if self._orbitRoot ~= root then
        self._orbitRoot, self._orbitStart, self._orbitAt = root, now, nil
        self._orbitAngle = self._random:NextNumber(0, math.pi * 2)
    end
    local radius = math.max(number(aa.Radius, 12, 4, 500), positions.GetStandOff(target, ownRoot))
    local height = number(aa.Height, 3, -50, 50)
    local angle
    if aa.PositionMode == "Random" then
        local interval = number(aa.RepositionMS, 100, 1, 1000) / 1000
        if self._orbitAt == nil or now - self._orbitAt >= interval then
            local old = self._orbitAngle
            self._orbitAngle = old + self._random:NextNumber(math.pi * 0.5, math.pi * 1.5)
            self._orbitHeight = height + self._random:NextNumber(-radius * 0.25, radius * 0.25)
            self._orbitAt = now
        end
        angle, height = self._orbitAngle, self._orbitHeight
    else
        angle = self._orbitAngle + (now - self._orbitStart) * math.rad(number(aa.OrbitSpeed, 120, -720, 720))
    end
    local point = root.Position + Vector3.new(math.cos(angle) * radius, height, math.sin(angle) * radius)
    return self:OrientPose(CFrame.new(point), config)
end

function Runtime:VoidPose(config)
    local settings = config.VoidSpam
    if settings == nil or not settings.Enabled then return nil end
    local now = self._clock()
    local interval = number(settings.IntervalMS, 1, 1, 1000) / 1000
    if self._voidAt == nil or now - self._voidAt >= interval then
        local previous = self._voidPoint
        local minimum = number(settings.MinDistance,100000,10000,1000000)
        local point
        for _ = 1, 8 do
            point = Vector3.new(self._random:NextNumber(-minimum,minimum),self._random:NextNumber(minimum,minimum*3),self._random:NextNumber(-minimum,minimum))
            if previous == nil or (point - previous).Magnitude >= minimum then break end
        end
        if previous ~= nil and (point-previous).Magnitude < minimum then
            point = Vector3.new(previous.X<=0 and minimum or -minimum, minimum*2, previous.Z<=0 and minimum or -minimum)
        end
        self._voidPoint, self._voidAt = point, now
    end
    return self:OrientPose(CFrame.new(self._voidPoint), config)
end

function Runtime:IdlePose(target, ownRoot, config)
    return self:VoidPose(config) or self:OrbitPose(target, ownRoot, config)
end

local function jointGroup(joint)
    local name = joint.Name
    if joint:IsA("Motor6D") and joint.Part1 ~= nil then name = joint.Part1.Name end
    name = string.lower(name)
    if string.find(name, "head", 1, true) or string.find(name, "neck", 1, true) then return "Head" end
    if string.find(name, "arm", 1, true) or string.find(name, "hand", 1, true) then return "Arms" end
    if string.find(name, "leg", 1, true) or string.find(name, "foot", 1, true) then return "Legs" end
    if string.find(name, "torso", 1, true) or string.find(name, "spine", 1, true) then return "Torso" end
end

function Runtime:RestoreJoints()
    if self._model == nil and next(self._joints) == nil then return end
    for joint, record in pairs(self._joints) do
        pcall(function()
            if joint.Parent ~= nil and joint.Transform == record.Applied then joint.Transform = record.Base end
        end)
    end
    self._joints = {}
    self._model = nil
end

function Runtime:ApplyJoints(model, config)
    local aa = config.AntiAim
    local localPose = aa and aa.LocalPose
    if model == nil or aa == nil or not aa.Enabled or localPose == nil or not localPose.Enabled then
        self:RestoreJoints(); return
    end
    if self._model ~= model then
        self:RestoreJoints()
        self._model = model
        for _, joint in ipairs(model:GetDescendants()) do
            if joint:IsA("Motor6D") or joint:IsA("Bone") then
                local group = jointGroup(joint)
                if group ~= nil then self._joints[joint] = { Group = group, Base = joint.Transform } end
            end
        end
    end
    for joint, record in pairs(self._joints) do
        if joint.Parent ~= nil then
            local current = joint.Transform
            if current ~= record.Applied then record.Base = current end
            local part = localPose.Parts[record.Group] or {}
            local offset = CFrame.fromOrientation(math.rad(number(part.Pitch, 0, -180, 180)),
                math.rad(number(part.Yaw, 0, -180, 180)), math.rad(number(part.Roll, 0, -180, 180)))
            record.Applied = record.Base * offset
            joint.Transform = record.Applied
        end
    end
end

function Runtime:Reset()
    self:RestoreJoints()
    self._orbitRoot, self._orbitAt, self._orbitStart = nil, nil, nil
    self._manipulation, self._viewAngles = nil, nil
    self._voidPoint, self._voidAt, self._yawAt = nil, nil, nil
end

return Runtime
end

