local function fn35()


local function finite(n) return type(n) == "number" and n == n and math.abs(n) < math.huge end
local function valid(p) return p and finite(p.X) and finite(p.Y) and finite(p.Z) end
local function look(from, to)
    local x,y,z = to.X-from.X, to.Y-from.Y, to.Z-from.Z
    local scale = math.max(math.abs(x),math.abs(y),math.abs(z))
    local direction = scale > 0.00001 and Vector3.new(x/scale,y/scale,z/scale) or Vector3.new(0,-1,0)
    local up = math.abs(direction.Y) > 0.99 and Vector3.new(1,0,0) or Vector3.new(0,1,0)
    return CFrame.new(from) * CFrame.lookAt(Vector3.zero, direction, up)
end

return {
    Build = function(part, origin)
        if part == nil or not valid(origin) then return nil end
        local size = part.Size
        if not valid(size) or size.X <= 0 or size.Y <= 0 or size.Z <= 0 then return nil end
        local localPoint
        local ok, surface = pcall(function() return part:GetClosestPointOnSurface(origin) end)
        if ok and valid(surface) then localPoint = part.CFrame:PointToObjectSpace(surface) end
        if not valid(localPoint) then localPoint = part.CFrame:PointToObjectSpace(origin) end
        if not valid(localPoint) then return nil end
        local hx,hy,hz = math.max(size.X*0.5-0.02,0.001), math.max(size.Y*0.5-0.02,0.001), math.max(size.Z*0.5-0.02,0.001)
        localPoint = Vector3.new(math.clamp(localPoint.X,-hx,hx), math.clamp(localPoint.Y,-hy,hy), math.clamp(localPoint.Z,-hz,hz))
        if math.abs(localPoint.X)+math.abs(localPoint.Y)+math.abs(localPoint.Z) < 0.00001 then localPoint = Vector3.new(0,hy,0) end
        local point = part.CFrame:PointToWorldSpace(localPoint)
        if not valid(point) then return nil end
        return { Part = part, ObjectSpace = localPoint }, look(origin, point)
    end,
}
end

