local function fn35()


local Fire = {}
Fire.__index = Fire

local function finite(n) return type(n)=="number" and n==n and math.abs(n)<math.huge end
local function valid(v) return v and finite(v.X) and finite(v.Y) and finite(v.Z) end
local function read(item, key)
    if item == nil then return nil end
    local ok, value = pcall(function() return item:Get(key) end)
    if ok and value ~= nil then return value end
    local data = item.Data
    return type(data)=="table" and data[key] or nil
end

function Fire.look(from, to)
    local dx,dy,dz = to.X-from.X,to.Y-from.Y,to.Z-from.Z
    local scale = math.max(math.abs(dx),math.abs(dy),math.abs(dz))
    local direction = scale>0.00001 and Vector3.new(dx/scale,dy/scale,dz/scale) or Vector3.new(0,-1,0)
    local up = math.abs(direction.Y)>0.99 and Vector3.new(0,0,1) or Vector3.new(0,1,0)
    return CFrame.new(from)*CFrame.lookAt(Vector3.zero,direction,up)
end

function Fire.new(api, random)
    assert(api.Utility and type(api.Utility.EncodeCFrame)=="function", "native CFrame encoder unavailable")
    return setmetatable({_api=api,_random=random or Random.new(),_enums={}},Fire)
end

function Fire:Enum(name, fallback)
    local value=self._enums[name]
    if value==nil then
        local ok,result=pcall(self._api.EnumLibrary.ToEnum,self._api.EnumLibrary,name)
        if ok then value=result end
        if value==nil and fallback then value=self._api.EnumLibrary:ToEnum(fallback) end
        self._enums[name]=value
    end
    assert(value~=nil,"missing action enum: "..name)
    return value
end

function Fire:Bake(part, predicted, scatter)
    if part==nil or part.Parent==nil or not valid(part.Position) or not valid(predicted) then return nil end
    local size=part.Size
    if not valid(size) or size.X<=0 or size.Y<=0 or size.Z<=0 then return nil end
    local p=part.CFrame:PointToObjectSpace(predicted)
    if not valid(p) then return nil end
    local x=math.max(size.X*0.5-0.08,0.001)
    local y=math.max(size.Y*0.5-0.08,0.001)
    local z=math.max(size.Z*0.5-0.08,0.001)
    local spread=math.min(scatter or 0.02,x*0.1,y*0.1,z*0.1)
    local function jitter() return self._random:NextNumber(-spread,spread) end
    p=Vector3.new(math.clamp(p.X+jitter(),-x,x),math.clamp(p.Y+jitter(),-y,y),math.clamp(p.Z+jitter(),-z,z))
    return p,part.CFrame:PointToWorldSpace(p)
end




function Fire:Reload(item,canSend)
    local id=read(item,"ObjectID")
    if id==nil then return false,"missing weapon ObjectID" end
    local action,payload="StartReloading",nil
    if type(item.StartReloading)=="function" then
        local result=table.pack(item:StartReloading())
        if not result[1] then return false,"native reload declined" end
        if type(result[2])~="string" then return false,"invalid native reload action" end
        action=result[2];payload={}
        for index=3,result.n do payload[utf8.char(index-2)]=result[index] end
    else
        local reload=self:Enum("Reload")
        payload={["\1"]=reload,["\2"]=reload}
    end
    if canSend and not canSend() then return false,"reload cancelled" end
    self._api.UseItemRemote:FireServer(id,self:Enum(action),payload,nil)
    return true
end



function Fire:MeleeAnimation(item)
    local heavy=item.Name=="Knife"
    local prefix=heavy and "HeavyAttack" or "Attack"
    return self:Enum(prefix.."Animation1",prefix.."1")
end

function Fire:Cooldown(item,melee)
    local info=item.Info or {}
    local duration
    if melee then duration=item.Name=="Knife" and info.HeavyAttackCooldown or info.AttackCooldown
    else
        local cooldown=item.Name=="Revolver" and info.QuickShotCooldown or info.ShootCooldown
        local burst=math.clamp(math.floor(tonumber(info.ShootBurst) or 1),1,32)
        local interval=math.max(0,tonumber(info.ShootBurstCooldown) or 0)
        duration=(burst-1)*interval+math.max(tonumber(cooldown) or 0,interval)
    end
    if not finite(duration) or duration<=0 then duration=melee and (item.Name=="Knife" and .625 or .2) or .1 end
    return math.clamp(duration,1/60,5)
end

function Fire:Send(item, part, origin, velocity, settings, melee)
    local objectId=read(item,"ObjectID")
    if objectId==nil then return 0,"missing weapon ObjectID" end
    if not part or not part.Parent then return 0,"target part removed" end
    local count=melee and 1 or math.clamp(math.floor(tonumber(settings.BurstRequests) or 2),1,4)
    local sent=0
    local info=item.Info or {}
    local animation
    if melee then
        local reason
        animation,reason=self:MeleeAnimation(item)
        if animation==nil then return 0,reason end
    end
    local predicted=part.Position
    if settings.Prediction==true and not melee and valid(velocity) then
        local speed=tonumber(info.ProjectileSpeed)
        if speed and speed>0 and speed<math.huge and info.IsRaycast~=true then
            local travel=math.min((part.Position-origin).Magnitude/speed,0.25)
            predicted=predicted+velocity*travel
        end
    end
    local encode=function(cf) return self._api.Utility:EncodeCFrame(cf) end
    for _=1,count do
        local objectPoint,worldPoint=self:Bake(part,predicted,0.02)
        if objectPoint==nil then break end
        local eye=Fire.look(origin,worldPoint)
        local muzzlePosition=origin+eye.LookVector*0.3+Vector3.new(0,tonumber(settings.MuzzleUp) or 0.4,0)
        local muzzle=Fire.look(muzzlePosition,worldPoint)
        local inner={ ["\0"]=encode(eye),["\1"]=encode(muzzle),["\2"]=part,["\3"]=encode(CFrame.new(objectPoint)) }
        
        
        if not melee and item.Name=="Revolver" then inner["\4"]=true end
        local envelope={ ["\1"]=inner }
        local action="StartShooting"
        if melee then
            action=item.Name=="Knife" and "StartAiming" or "StartShooting"
            envelope["\2"]=animation
        elseif info.IsRaycast==true then envelope["\2"]=true end
        self._api.UseItemRemote:FireServer(objectId,self:Enum(action),envelope,nil)
        sent+=1
    end
    return sent
end

Fire.read=read
Fire.valid=valid
return Fire
end

