local function fn35()



local Transport={}
Transport.__index=Transport
function Transport.new(runService, id)
    local self=setmetatable({_service=runService,_id=id,_connections={}},Transport)
    runService:BindToRenderStep(id,Enum.RenderPriority.Camera.Value-1,function() self:Restore() end)
    self._simulationSteps=0
    self._connections[1]=runService.PreSimulation:Connect(function()
        local pulse=self._oneFrame
        if pulse and pulse.Active then
            self._oneFrame=nil
            self:Park(pulse.Return,true)
            pcall(pulse.Done,self._simulationSteps-pulse.Step,os.clock()-pulse.Start)
        elseif pulse then
            local ok,valid=pcall(pulse.Valid)
            local placed,pose=false,nil
            if ok and valid then placed,pose=pcall(pulse.Pose) end
            if placed and pose then
                pulse.Active=true;pulse.Start=os.clock();pulse.Step=self._simulationSteps
                self:Park(pose,true)
            else self:CancelOneFrame() end
        end
        
        
        if self._simulationPose then
            if self:Park(self._simulationPose,true) then self._simulationSteps+=1 end
        else self:Restore() end
    end)
    return self
end

function Transport:HasOneFrame() return self._oneFrame~=nil end
function Transport:ArmOneFrame(pose,returnPose,valid,done)
    if self._oneFrame or not self._root or not self._root.Parent then return false end
    self._oneFrame={Pose=pose,Return=returnPose,Valid=valid,Done=done,Active=false}
    return true
end
function Transport:CancelOneFrame()
    local pulse=self._oneFrame
    self._oneFrame=nil
    if pulse and pulse.Active then self:Park(pulse.Return,true) end
end

function Transport:Bind(controller,root)
    if self._root==root and self._controller==controller then return end
    self:Release()
    self._controller,self._root=controller,root
    self._driver=controller and controller._rootDesync
    if self._driver then
        self._driver:_RenderStepUpdate()
        self._driver._cframe=nil
        self._driver._oldCFrame=nil
        self._driver._externalTransport=self
    end
end

function Transport:GetClientCFrame()
    return self._home or (self._root and self._root.CFrame)
end

function Transport:BeginFrame()
    self:Restore()
    if not self._root or not self._root.Parent then return nil end
    self._home=self._root.CFrame
    return self._home
end

function Transport:GetSimulationSteps() return self._simulationSteps end

function Transport:Park(cf,forSimulation)
    local root=self._root
    if root==nil or root.Parent==nil or cf==nil then return false end
    if self._home==nil then self:BeginFrame() end
    self._parked=true
    root.CFrame=cf
    self._pose=cf
    self._simulationPose=forSimulation and cf or nil
    return true
end

function Transport:Restore()
    if not self._parked then return end
    self._parked=false
    local root=self._root
    if root and root.Parent and self._home then
        root.CFrame=self._home
    end
end

function Transport:Release()
    self:CancelOneFrame()
    self._simulationPose=nil
    self:Restore()
    if self._driver and self._driver._externalTransport==self then self._driver._externalTransport=nil end
    self._driver,self._controller,self._root,self._home,self._pose=nil,nil,nil,nil,nil
end

function Transport:Destroy()
    self:Release()
    self._service:UnbindFromRenderStep(self._id)
    for _,c in ipairs(self._connections) do c:Disconnect() end
end
return Transport
end

