local function fn35()
local PullDown={}
PullDown.__index=PullDown

local function number(value,fallback,low,high)
    value=tonumber(value)
    if not value or value~=value or math.abs(value)==math.huge then value=fallback end
    return math.clamp(value,low,high)
end
local function read(item,key)
    local ok,value=pcall(function() return item:Get(key) end)
    if ok and value~=nil then return value end
    return type(item.Data)=="table" and item.Data[key] or nil
end

function PullDown.new(context,deps)
    deps=deps or {}
    local self=setmetatable({
        _context=context,_api=deps.API or tbl17.aS(),_store=deps.Store or tbl17.bG(),
        _input=deps.Input or cloneref(game:GetService("UserInputService")),
        _move=deps.Move or mousemoverel,_clock=deps.Clock or tick,
        _menuOpen=deps.MenuOpen or function()
            local menu=getgenv().KiciaMenu
            return menu and (menu.Visible or (menu._engine and menu._engine:IsVisible()))
        end,
        _fraction=0,_firingUntil=0,_focused=true,_connections={},
        _stats={Status="Idle",Pixels=0,Updates=0,Errors=0},
    },PullDown)
    if self._input.WindowFocusReleased then
        self._connections[#self._connections+1]=self._input.WindowFocusReleased:Connect(function()
            self._focused=false;self:_reset("Window unfocused")
        end)
        self._connections[#self._connections+1]=self._input.WindowFocused:Connect(function() self._focused=true end)
    end
    return self
end

function PullDown:_reset(status)
    self._fraction=0;self._firingUntil=0
    self._stats.Status=status
end

function PullDown:_update(dt)
    local config=self._store.Data.Ragebot.WildcatPullDown or {}
    if config.Enabled~=true then self:_reset("Disabled");return end
    local fighter=self._api.FighterController.LocalFighter
    local item=fighter and fighter.EquippedItem
    
    if not item or item.Name~="Wildcat" then
        self._item=nil;self:_reset("Not Wildcat");return
    end
    local ammo=read(item,"Ammo")
    local cooldown=tonumber(item._shoot_cooldown) or 0
    local now=self._clock()
    local changed=self._item==item and ((cooldown>0 and cooldown~=self._lastCooldown)
        or (type(ammo)=="number" and type(self._lastAmmo)=="number" and ammo<self._lastAmmo))
    if self._item~=item then self:_reset("Wildcat equipped") end
    self._item,self._lastCooldown,self._lastAmmo=item,cooldown,ammo
    if config.Enabled~=true then self:_reset("Disabled");return end
    local inner=self._context.Inner
    local state=inner and inner.FighterState.Character.State
    if not state or not state.Alive then self:_reset("Not alive");return end
    if not self._focused or self._menuOpen() or self._input:GetFocusedTextBox()~=nil then
        self:_reset("Input paused");return
    end
    if not self._input:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
        self:_reset("Fire released");return
    end
    if (tonumber(item._reload_cooldown) or 0)>now then self:_reset("Reloading");return end
    if type(ammo)=="number" and ammo<=0 then self:_reset("Empty weapon");return end
    local recent=cooldown>now and cooldown<now+5
    if changed or recent then
        local interval=number(item.Info and item.Info.ShootCooldown,.1,.02,.25)
        self._firingUntil=now+interval+.025
    end
    if now>=self._firingUntil then
        self:_reset("Waiting for shot");return
    end
    if type(self._move)~="function" then self:_reset("Mouse movement unavailable");return end
    local strength=number(config.Strength,120,0,600)
    self._fraction+=strength*number(dt,0,0,.05)
    local pixels=math.floor(self._fraction)
    self._fraction-=pixels
    self._stats.Status="Pulling down"
    if pixels>0 then
        self._move(0,pixels)
        self._stats.Pixels+=pixels
    end
end

function PullDown:Update(dt)
    if self._destroyed then return end
    self._stats.Updates+=1
    local ok,err=pcall(self._update,self,dt)
    if not ok then
        self._stats.Errors+=1;self._stats.LastError=tostring(err)
        self:_reset("Input error")
    end
end
function PullDown:GetDebugState() return table.clone(self._stats) end
function PullDown:Destroy()
    self._destroyed=true;self:_reset("Unloaded")
    for _,connection in ipairs(self._connections) do connection:Disconnect() end
end
return PullDown
end

