local function fn35()

local Compat={}
function Compat.Owner(object,name)
    local seen={}
    while type(object)=="table" and not seen[object] do
        seen[object]=true
        if type(rawget(object,name))=="function" then return object,rawget(object,name) end
        local mt=getmetatable(object)
        object=type(mt)=="table" and rawget(mt,"__index") or nil
    end
end
function Compat.Wrap(object,name,build)
    local owner,original=Compat.Owner(object,name)
    if not owner then return nil,"Native method unavailable: "..name end
    local replacement=build(original)
    if type(replacement)~="function" then return nil,"Invalid wrapper: "..name end
    rawset(owner,name,replacement)
    local record={Owner=owner,Name=name,Original=original,Replacement=replacement}
    function record:Restore()
        if rawget(self.Owner,self.Name)==self.Replacement then rawset(self.Owner,self.Name,self.Original) end
    end
    return record
end


local function preserveRemoteMethod(bus, restore)
    if not bus or bus.PreservesRemoteMethod or type(restore)~="function" then return bus end
    local route=bus.Route
    bus.Route=function(self,original,remote,method,...)
        local function forward(instance,...)
            pcall(restore,method)
            return original(instance,...)
        end
        return route(self,forward,remote,method,...)
    end
    bus.PreservesRemoteMethod=true
    return bus
end

local function router()
    local env=getgenv()
    local bus=env.AbsenseRivalsRemoteRouter
    if bus then return preserveRemoteMethod(bus,K.fn("setnamecallmethod")) end
    bus={Routes={FireServer={},InvokeServer={}},Depth=setmetatable({},{__mode="k"}),Subscriptions=0}
    env.AbsenseRivalsRemoteRouter=bus
    local function same(a,b)
        if a==b then return true end
        if type(compareinstances)=="function" then local ok,v=pcall(compareinstances,a,b);return ok and v end
        return false
    end
    function bus:Report(where,problem)
        local run=getgenv().KiciaRun
        if run and run.RecordError then run.RecordError(where,problem) else warn("[Kicia] "..where..": "..tostring(problem)) end
    end
    function bus:Route(original,remote,method,...)
        local routes=self.Routes[method]
        local thread=coroutine.running()
        if self.Subscriptions==0 or not routes or self.Depth[thread] or typeof(remote)~="Instance" then return original(remote,...) end
        local bucket=routes[remote.Name]
        if not bucket then return original(remote,...) end
        local matching={}
        for _,record in ipairs(bucket) do
            if record.Active and same(record.Remote,remote) then matching[#matching+1]=record end
        end
        if #matching==0 then return original(remote,...) end
        self.Depth[thread]=true
        local packet={Args=table.pack(...),Block=false,Remote=remote,Method=method}
        for _,record in ipairs(matching) do if record.Before then
            local snapshot=table.clone(packet.Args)
            local ok,err=pcall(record.Before,packet)
            if not ok then packet.Args=snapshot;packet.Block=false;self:Report(record.Label,err) end
        end end
        local results
        if packet.Block then results=table.pack(true,table.unpack(packet.Results or {},1,packet.Results and packet.Results.n or 0))
        else results=table.pack(pcall(original,remote,table.unpack(packet.Args,1,packet.Args.n))) end
        if results[1] then
            packet.Results={n=results.n-1};for i=2,results.n do packet.Results[i-1]=results[i] end
            for _,record in ipairs(matching) do if record.After then
                local snapshot=table.clone(packet.Results)
                local ok,err=pcall(record.After,packet)
                if not ok then packet.Results=snapshot;self:Report(record.Label,err) end
            end end
        end
        self.Depth[thread]=nil
        if not results[1] then error(results[2],0) end
        return table.unpack(packet.Results,1,packet.Results.n)
    end
    local hookmeta=K.fn("hookmetamethod")
    local hookfn=K.fn("hookfunction")
    local getmethod=K.fn("getnamecallmethod")
    local closure=K.fn("newcclosure") or function(fn)return fn end
    if hookmeta and getmethod then
        local previous
        local replacement=closure(function(self,...)
            local method=getmethod()
            if method~="FireServer" and method~="InvokeServer" then return previous(self,...) end
            return bus:Route(previous,self,method,...)
        end)
        local ok,result=pcall(hookmeta,game,"__namecall",replacement)
        if ok then previous=result;bus.Namecall=true end
    end
    if hookfn then
        for _,spec in ipairs({{"RemoteEvent","FireServer"},{"RemoteFunction","InvokeServer"}}) do
            local instance=Instance.new(spec[1]);local target=instance[spec[2]];instance:Destroy()
            local previous
            local replacement=closure(function(self,...)return bus:Route(previous,self,spec[2],...)end)
            local ok,result=pcall(hookfn,target,replacement)
            if ok then previous=result;bus[spec[2]]=true end
        end
    end
    return preserveRemoteMethod(bus,K.fn("setnamecallmethod"))
end
function Compat.Remote(remote,callbacks)
    local method=remote:IsA("RemoteFunction") and "InvokeServer" or "FireServer"
    local bus=router()
    if not bus.Namecall and not bus[method] then return nil,"Executor remote hooks unavailable" end
    local routes=bus.Routes[method]
    local name=remote.Name
    routes[name]=routes[name] or {}
    local record={Remote=remote,Before=callbacks.Before,After=callbacks.After,Label=callbacks.Label or name,Active=true}
    routes[name][#routes[name]+1]=record;bus.Subscriptions+=1
    function record:Restore()
        if not self.Active then return end
        self.Active=false;bus.Subscriptions-=1
        local bucket=routes[name]
        local i=table.find(bucket,self);if i then table.remove(bucket,i) end
        if #bucket==0 then routes[name]=nil end
    end
    return record
end
return Compat
end

