local kiciaAutoLoad = (function()
    local Cache = {}
    Cache.__index = Cache
    local SOURCE_PATH = "absense/rerun.lua"
    local META_PATH = "absense/rerun.json"
    local ENABLED_PATH = "absense/autoload.enabled"

    
    
    local DISPATCHER = [==[
local env = type(getgenv)=="function" and getgenv() or _G
if env.__KiciaAutoLoadBusy or env.__AbsenseAutoLoadBusy then return end
env.__KiciaAutoLoadBusy=true
env.__AbsenseAutoLoadBusy=true
local ok,problem=xpcall(function()
    local players=game:GetService("Players")
    local deadline=os.clock()+60
    local function ready()
        local player=players.LocalPlayer
        local gui=player and player:FindFirstChildOfClass("PlayerGui")
        return game:IsLoaded() and gui and #gui:GetChildren()>0
    end
    while not ready() and os.clock()<deadline do task.wait(0.5) end
    if not ready() then error("The game did not finish loading within 60 seconds",0) end
    task.wait(10)
    if readfile("absense/autoload.enabled")~="1" then return end
    local source=readfile("absense/rerun.lua")
    local manifest=game:GetService("HttpService"):JSONDecode(readfile("absense/rerun.json"))
    local build=source:match('K%.Diagnostics%s*=%s*{%s*Build%s*=%s*"([^"]+)"')
    if type(manifest)~="table" or manifest.Format~=1 or manifest.Build~=build or manifest.Bytes~=#source then
        error("Saved source and cache manifest do not match; run the packaged Kicia file to repair the cache",0)
    end
    local live=env.KiciaRun
    if live and not live.destroyed and live.Diagnostics and live.Diagnostics.Build==build then return end
    local chunk,compileError=loadstring(source,"@kicia/rerun.lua")
    if not chunk then error("Saved source could not compile: "..tostring(compileError),0) end
    local launch={Build=build,Source=source}
    env.__KiciaLaunch=launch
    local ran,runError=xpcall(chunk,debug.traceback)
    if env.__KiciaLaunch==launch then env.__KiciaLaunch=nil end
    if not ran then error(runError,0) end
end,debug.traceback)
env.__KiciaAutoLoadBusy=nil
env.__AbsenseAutoLoadBusy=nil
if not ok then warn("[Kicia] Auto Load: "..tostring(problem)) end
]==]

    local function buildOf(source)
        return type(source)=="string" and source:match('K%.Diagnostics%s*=%s*{%s*Build%s*=%s*"([^"]+)"') or nil
    end

    function Cache.new(runtime)
        local env=type(getgenv)=="function" and getgenv() or _G
        local launch=env.__KiciaLaunch or env.__AbsenseLaunch
        local self=setmetatable({Runtime=runtime,Status="Not cached",Armed=false},Cache)
        if type(launch)=="table" and launch.Build==runtime.Diagnostics.Build
            and buildOf(launch.Source)==runtime.Diagnostics.Build then
            self.Source=launch.Source
        end
        self.Read=runtime.fn("readfile")
        self.Write=runtime.fn("writefile")
        self.MakeFolder=runtime.fn("makefolder")
        self.IsFolder=runtime.fn("isfolder")
        self.Queue=runtime.fn("queue_on_teleport") or runtime.fn("queueonteleport")
        return self
    end

    function Cache:_folder()
        if self.IsFolder and self.IsFolder("absense") then return end
        if self.MakeFolder then
            local ok,problem=pcall(self.MakeFolder,"absense")
            if not ok and not (self.IsFolder and self.IsFolder("absense")) then error(problem,0) end
        end
    end

    function Cache:Sync()
        if not self.Read or not self.Write then
            self.Status="Executor file access unavailable"
            return false,self.Status
        end
        local ok,problem=pcall(function()
            self:_folder()
            local readOK,existing=pcall(self.Read,SOURCE_PATH)
            if not self.Source and readOK and buildOf(existing)==self.Runtime.Diagnostics.Build then
                self.Source=existing
            end
            if not self.Source then
                error("This raw script has no source to cache; use the packaged Kicia download",0)
            end
            if not readOK or existing~=self.Source then
                self.Write(SOURCE_PATH,self.Source)
                if self.Read(SOURCE_PATH)~=self.Source then error("Saved script verification failed",0) end
            end
            local http=game:GetService("HttpService")
            local manifest=http:JSONEncode({Format=1,Build=self.Runtime.Diagnostics.Build,Bytes=#self.Source})
            self.Write(META_PATH,manifest)
            local saved=http:JSONDecode(self.Read(META_PATH))
            if saved.Build~=self.Runtime.Diagnostics.Build or saved.Bytes~=#self.Source then
                error("Cache manifest verification failed",0)
            end
        end)
        self.Status=ok and "Ready" or tostring(problem)
        return ok,self.Status
    end

    function Cache:SetEnabled(enabled)
        self.Enabled=enabled==true
        if not self.Enabled then
            if self.Write then
                local ok,problem=pcall(function() self:_folder();self.Write(ENABLED_PATH,"0") end)
                if not ok then return false,tostring(problem) end
            end
            return true
        end
        local synced,problem=self:Sync()
        if not synced then return false,problem end
        if not self.Queue then return false,"Executor teleport queue unavailable" end
        local ok,reason=pcall(function()
            self.Write(ENABLED_PATH,"1")
            if self.Read(ENABLED_PATH)~="1" then error("Could not save the Auto Load setting",0) end
            if not self.Armed then self.Queue(DISPATCHER);self.Armed=true end
        end)
        if not ok then self.Status=tostring(reason) end
        return ok,reason
    end

    function Cache:GetStatus()
        return {Status=self.Status,Build=self.Runtime.Diagnostics.Build,Path=SOURCE_PATH,
            SourceAvailable=self.Source~=nil,Enabled=self.Enabled==true,Armed=self.Armed}
    end
    return Cache
end)()

