local function initialize()



pcall(function()
    local isfolder_, listfiles_, readfile_, writefile_, makefolder_ = isfolder, listfiles, readfile, writefile, makefolder
    if type(isfolder_) ~= "function" or type(listfiles_) ~= "function" then return end
    if not isfolder_("absense") then return end
    if type(readfile_) ~= "function" or type(writefile_) ~= "function" then return end
    if isfolder_("absense") then return end
    if type(makefolder_) == "function" then pcall(makefolder_, "absense") end
    for _, f in ipairs(listfiles_("absense")) do
        pcall(function()
            local rel = string.gsub(tostring(f), ".*absense[\\/]", "")
            rel = string.gsub(rel, "\\", "/")
            if rel ~= "" then
                local dir = string.match(rel, "^(.+)/[^/]+$")
                if dir and makefolder_ then
                    local acc = "absense"
                    for seg in string.gmatch(dir, "[^/]+") do
                        acc = acc .. "/" .. seg
                        pcall(makefolder_, acc)
                    end
                end
                writefile_("absense/" .. rel, readfile_("absense/" .. rel))
            end
        end)
    end
end)

