    local cosmetics=runtime.Cosmetics
    local native=K.Native
    local router=getgenv().AbsenseRivalsRemoteRouter
    local function loaded(object,key)return object~=nil and rawget(object,key or "_restore")~=nil end
    return {
        Build=K.Diagnostics.Build,AutoLoad=K.AutoLoad:GetStatus(),PlaceId=game.PlaceId,PlaceVersion=game.PlaceVersion,
        Errors=K.Diagnostics.Errors,Calls=K.Diagnostics.Calls,Context=context~=nil,
        Equipped=context and context.ItemBehaviors:GetEquippedGunName(),
        InputHook=loaded(input),ProfileHook=loaded(runtime.ProfileHook),
        CosmeticHooks=cosmetics and cosmetics._items and cosmetics._items._rendering._viewModelHook._restore~=nil or false,
        RemoteSubscriptions=router and router.Subscriptions or 0,
        QuickAttackClass=native.QuickAttackFunction.ClassName,
        Rage=K.Ragebot and K.Ragebot:GetDebugState()or nil,
    }
end



